// Visual explainers for the Storage roadmap. Schema: CONTRIBUTING.md → "Visuals".
'use strict';

// ===== Module 1: Storage Fundamentals =========================================

registerDiagram({
  id: 'stor-ssd-ftl-gc',
  roadmap: 'storage', module: 1, topic: 'SSDs and NVMe: NAND, FTL, Write Amplification, TRIM and Wear Levelling',
  kind: 'graph',
  title: 'Inside an SSD: out-of-place writes, garbage collection, write amplification',
  desc: 'NAND pages can be programmed but not overwritten, and erase works only on whole blocks. Follow one overwrite of LBA 7 to see why the FTL, garbage collection and over-provisioning exist, and where write amplification comes from.',
  groups: [
    { id: 'ctrl', label: 'SSD controller', x: 2, y: 0, w: 1, h: 4, color: 'blue' },
    { id: 'nand', label: 'NAND flash', x: 4, y: 0, w: 3, h: 4, color: 'green' },
  ],
  nodes: [
    { id: 'host', label: 'Host', sub: 'NVMe driver', icon: '🖥️', x: 0, y: 1, color: 'gray', info: 'The OS only sees logical block addresses (LBAs). It has no idea where data physically lives on the flash; that indirection is the whole job of the FTL.' },
    { id: 'ftl', label: 'FTL map', sub: 'LBA → physical page', x: 2, y: 1, color: 'blue', info: 'The Flash Translation Layer keeps an LBA to physical-page table, usually in on-drive DRAM (about 1 GB of DRAM per 1 TB of flash at 4 KiB granularity). Every write updates this map instead of overwriting data in place.' },
    { id: 'gc', label: 'Garbage collector', sub: 'picks victim blocks', x: 2, y: 3, color: 'purple', info: 'Background (or, on a full drive, foreground) process that reclaims blocks full of stale pages. When it runs in the foreground, host writes wait behind it: the classic SSD latency cliff.' },
    { id: 'blkA', label: 'Block A', sub: '256 pages x 16 KiB', x: 4, y: 0, color: 'orange', info: 'An erase block: hundreds of pages, several MiB. Pages are read and programmed individually, but the only way to make a page writable again is to erase the entire block.' },
    { id: 'blkB', label: 'Block B (open)', sub: 'next free page', x: 4, y: 2, color: 'green', info: 'The block currently receiving new writes. Writes fill it page by page, sequentially, regardless of which LBAs the host is writing.' },
    { id: 'pool', label: 'Free pool', sub: 'erased blocks', x: 6, y: 0, color: 'teal', info: 'Erased blocks ready to be programmed. Wear levelling chooses the least-worn block from here, and occasionally moves cold data so rarely-written blocks also take their share of P/E cycles.' },
    { id: 'spare', label: 'Spare block', sub: 'over-provisioning', x: 6, y: 2, color: 'teal', ghost: true, info: 'Hidden capacity (7% on consumer drives, 28% or more on write-heavy enterprise drives) that the host cannot address. More spare space means GC finds emptier victims, so it copies less and WAF drops.' },
  ],
  edges: [
    { from: 'host', to: 'ftl', label: 'NVMe write' },
    { from: 'ftl', to: 'blkA' },
    { from: 'ftl', to: 'blkB' },
    { from: 'gc', to: 'blkA' },
    { from: 'blkA', to: 'spare' },
    { from: 'blkA', to: 'pool', label: 'erase' },
  ],
  steps: [
    { caption: 'The host writes LBA 7. The FTL programs it into a free page of block A and records LBA 7 → A:page 0 in its map. Programming a page takes hundreds of microseconds; reads take tens.', flows: [{ from: 'host', to: 'ftl', label: 'LBA 7 v1' }, { from: 'ftl', to: 'blkA', label: 'program' }] },
    { caption: 'The host overwrites LBA 7. A programmed page cannot be rewritten, so the FTL writes v2 to the next free page in open block B, points the map at it, and merely marks A:page 0 as invalid.', flows: [{ from: 'host', to: 'ftl', label: 'LBA 7 v2' }, { from: 'ftl', to: 'blkB', label: 'program' }], active: ['blkA'] },
    { caption: 'After many overwrites, block A holds 200 invalid pages and 56 valid ones. The dead space cannot be reused yet: only a whole-block erase frees it.', active: ['blkA', 'ftl'] },
    { caption: 'Free blocks run low, so garbage collection picks a victim: the block with the most invalid pages, because it costs the least to clean.', flows: [{ from: 'gc', to: 'blkA', label: 'pick victim' }] },
    { caption: 'GC copies the 56 still-valid pages into a spare block and updates the map. These are writes the host never asked for, and they are the source of write amplification.', flows: [{ from: 'blkA', to: 'spare', label: 'copy 56 valid' }], active: ['gc'] },
    { caption: 'Block A is erased (a few milliseconds, one P/E cycle of a TLC budget of about 1,000 to 3,000) and goes back to the free pool. Wear levelling decides which free block gets used next.', flows: [{ from: 'blkA', to: 'pool', label: 'erase' }] },
    { caption: 'WAF = NAND writes / host writes. Here the host wrote 200 pages and NAND wrote 256, so WAF is 1.28. On a nearly full drive victims are mostly valid, WAF climbs to 3 to 5 or more, and foreground GC causes p99 latency spikes.', active: ['blkA', 'blkB', 'spare', 'gc'] },
    { caption: 'TRIM (NVMe Deallocate) tells the FTL that deleted LBAs are dead, so GC stops copying them. TRIM plus over-provisioning keeps victims emptier, which lowers WAF and stabilises tail latency.', flows: [{ from: 'host', to: 'ftl', label: 'TRIM LBAs' }], active: ['spare'] },
  ],
});

// ===== Module 2: Block, File & Object Storage =================================

registerDiagram({
  id: 'stor-block-file-object',
  roadmap: 'storage', module: 2, topic: 'Choosing Block vs File vs Object (AWS, Azure, Kubernetes)',
  kind: 'graph',
  title: 'Block vs file vs object: where the file system lives',
  desc: 'The three models differ mainly in where the file system (or naming layer) runs. That one fact explains sharing, latency, update semantics and scale. Press Play to follow a write down each path.',
  groups: [
    { id: 'host', label: 'Your host (VM / node)', x: 0, y: 0, w: 3, h: 5, color: 'gray' },
    { id: 'svc', label: 'Storage service', x: 4, y: 0, w: 3, h: 5, color: 'green' },
  ],
  nodes: [
    { id: 'app', label: 'Application', sub: 'pod or process', icon: '📦', x: 0, y: 1, h: 3, color: 'yellow', info: 'The same application can use all three: a database volume on block storage, shared assets on a file share, and blobs through an object-store SDK.' },
    { id: 'fs', label: 'ext4 / XFS', sub: 'FS runs on host', x: 2, y: 0, color: 'blue', info: 'With block storage the file system runs in your kernel. It caches metadata and assumes it is the only writer, which is why mounting one ext4 volume on two hosts corrupts it (unless you use a cluster file system).' },
    { id: 'nfsc', label: 'NFS / SMB client', sub: 'kernel, file handles', x: 2, y: 2, color: 'purple', info: 'Translates POSIX calls into NFS RPCs (LOOKUP, READ, WRITE, COMMIT, GETATTR). Client caching is why NFS gives close-to-open consistency rather than strict POSIX visibility.' },
    { id: 'sdk', label: 'SDK / HTTP client', sub: 'user space', x: 2, y: 4, color: 'orange', info: 'No kernel involvement: the app makes HTTPS requests (S3 API, Azure Blob REST) signed with SigV4 or a SAS token. No mount, no file descriptors, no partial overwrite.' },
    { id: 'vol', label: 'Block volume', sub: 'EBS / Azure Disk', x: 4, y: 0, shape: 'db', color: 'blue', info: 'Sees only numbered blocks (LBAs), never files. Replicated inside one AZ. Sub-millisecond latency, attached to one host at a time (multi-attach exists but needs a cluster-aware FS).' },
    { id: 'nfss', label: 'File server', sub: 'EFS / Azure Files', x: 4, y: 2, color: 'purple', info: 'Owns the file system, the directory tree and locks, so many clients can share one namespace. Metadata-heavy work (many small files, stat calls) pays a network round trip per operation.' },
    { id: 'front', label: 'Object API tier', sub: 'auth, routing', x: 4, y: 4, color: 'orange', info: 'Stateless front ends authenticate the request, look up or create the key in a metadata index, and stream bytes to storage nodes (usually erasure coded across 3 or more AZs).' },
    { id: 'blocks', label: 'Disks (LBAs)', sub: 'replicated in AZ', x: 6, y: 0, shape: 'db', color: 'teal', info: 'Underneath, the cloud provider stores your volume as replicated chunks on many servers, but the interface you get is a single virtual disk.' },
    { id: 'tree', label: 'Server dir tree', sub: 'POSIX semantics', x: 6, y: 2, shape: 'db', color: 'teal', info: 'Hierarchical namespace with permissions, rename, byte-range locks and in-place partial writes, shared by every client that mounts it.' },
    { id: 'bucket', label: 'Bucket: key → obj', sub: 'flat namespace', x: 6, y: 4, shape: 'db', color: 'teal', info: 'A flat map from key to immutable object plus metadata. "Folders" are just key prefixes. Updating one byte means uploading the whole object again; there is no atomic rename.' },
  ],
  edges: [
    { from: 'app', to: 'fs', label: 'write(fd)' },
    { from: 'app', to: 'nfsc', label: 'write(fd)' },
    { from: 'app', to: 'sdk', label: 'PutObject' },
    { from: 'fs', to: 'vol', label: 'LBA I/O' },
    { from: 'nfsc', to: 'nfss', label: 'NFS RPCs' },
    { from: 'sdk', to: 'front', label: 'HTTPS PUT' },
    { from: 'vol', to: 'blocks' },
    { from: 'nfss', to: 'tree' },
    { from: 'front', to: 'bucket' },
  ],
  steps: [
    { caption: 'Block: the app calls write(fd, offset). The file system on your own host maps the file offset to block numbers (LBAs) and decides where metadata goes.', flows: [{ from: 'app', to: 'fs', label: 'write 4 KiB' }] },
    { caption: 'Only LBA reads and writes cross the network (NVMe or iSCSI). The volume never sees file names, so only one host can safely mount it read-write. Latency is sub-millisecond, ideal for databases.', flows: [{ from: 'fs', to: 'vol', label: 'LBA 81920' }, { from: 'vol', to: 'blocks', label: 'replicate' }] },
    { caption: 'File: the same write(fd) goes to the NFS or SMB client in your kernel, which sends WRITE and COMMIT RPCs carrying a file handle and byte offset.', flows: [{ from: 'app', to: 'nfsc', label: 'write 4 KiB' }, { from: 'nfsc', to: 'nfss', label: 'WRITE + COMMIT' }] },
    { caption: 'The file system lives on the server, so many clients share one tree with locks and rename. The price is a network round trip per metadata operation and close-to-open (not strict) consistency.', flows: [{ from: 'nfss', to: 'tree', label: 'update file' }], active: ['nfsc'] },
    { caption: 'Object: the app sends PUT key with the entire object over HTTPS. There is no mount and no offset: to change one byte you upload the whole object again (or use multipart for large ones).', flows: [{ from: 'app', to: 'sdk', label: 'PutObject' }, { from: 'sdk', to: 'front', label: 'PUT /img/42.jpg' }] },
    { caption: 'The service stores the object under a key in a flat namespace and returns 200 when it is durable. Tens of ms per request, but effectively unlimited scale and the lowest cost per GB.', flows: [{ from: 'front', to: 'bucket', label: 'store + index' }] },
    { caption: 'Rule of thumb: block for databases and low-latency random writes (RWO PVC), file when several pods need the same POSIX tree (RWX PVC), object for large write-once data read by many services.', active: ['blocks', 'tree', 'bucket', 'fs', 'nfss', 'front'] },
  ],
});

registerDiagram({
  id: 'stor-multipart-presigned',
  roadmap: 'storage', module: 2, topic: 'Multipart Upload, Presigned URLs and Object-Store Performance',
  kind: 'sequence',
  title: 'Direct-to-S3 upload of a 20 GB file: presigned multipart',
  desc: 'Your API hands out short-lived signed URLs, the client uploads parts in parallel straight to the object store, and the object appears atomically on completion. Gigabytes never pass through your servers.',
  actors: [
    { id: 'c', label: 'Client', sub: 'browser / mobile', icon: '📱', color: 'gray', info: 'Holds no cloud credentials. It only ever sees an UploadId and presigned URLs that expire in minutes.' },
    { id: 'api', label: 'Your API', sub: 'holds IAM role', icon: '🖥️', color: 'blue', info: 'Authenticates the user, decides the object key, and signs URLs with its own credentials. It handles a few small JSON requests instead of 20 GB of traffic.' },
    { id: 's3', label: 'Object store', sub: 'S3 / Azure Blob', icon: '🪣', color: 'green', info: 'Verifies each signature and expiry, stores parts independently, and stitches them into one object on CompleteMultipartUpload. Azure equivalent: Put Block + Put Block List with SAS tokens.' },
  ],
  steps: [
    { section: 'Start the upload' },
    { from: 'c', to: 'api', label: 'POST /uploads 20 GB', caption: 'The client asks your API to upload a 20 GB video. The API authorizes the user and chooses the key, so clients cannot write wherever they like.' },
    { from: 'api', to: 's3', label: 'CreateMultipartUpload', caption: 'The API starts a multipart upload and receives an UploadId. A single PUT is capped at 5 GiB, so anything this large must be multipart; it is worth it above about 100 MB anyway.' },
    { from: 'api', to: 'api', label: 'presign 160 parts', caption: 'With 128 MiB parts, 20 GB is 160 parts (limits: 5 MiB to 5 GiB per part, at most 10,000 parts). Each UploadPart URL is signed with SigV4 and expires in, say, 15 minutes.' },
    { from: 'api', to: 'c', label: 'UploadId + URLs', reply: true, caption: 'The client gets the URLs. A leaked URL allows only that one operation on that one key until it expires.' },
    { section: 'Upload parts in parallel' },
    { from: 'c', to: 's3', label: 'PUT part 1..160 (8 at a time)', caption: 'The client PUTs parts directly to the object store over several parallel connections. First-byte latency is tens of ms, so parallelism is what fills the bandwidth.' },
    { from: 's3', to: 'c', label: 'ETag per part', reply: true, caption: 'Each part returns an ETag. A failed part is retried on its own, so a dropped connection at 19 GB costs one 128 MiB part, not the whole upload.' },
    { section: 'Complete' },
    { from: 'c', to: 'api', label: 'part numbers + ETags', caption: 'The client reports the ordered list of part numbers and ETags back to the API.' },
    { from: 'api', to: 's3', label: 'CompleteMultipart', caption: 'The API completes the upload. The object appears atomically: readers see either nothing or the whole 20 GB, never a partial file, and S3 reads are strongly consistent right after.' },
    { from: 's3', to: 'api', label: '200 + ETag', reply: true, caption: 'The final ETag is not the MD5 of the file but a hash of the part hashes with a "-160" suffix, so do not compare it with a local MD5.' },
    { from: 'api', to: 'api', label: 'abort stale parts', caption: 'Abandoned uploads keep billing for their stored parts and are invisible in normal listings. Add a lifecycle rule AbortIncompleteMultipartUpload (for example after 7 days).' },
  ],
});

// ===== Module 3: RAID, Replication & Durability ===============================

registerDiagram({
  id: 'stor-erasure-coding',
  roadmap: 'storage', module: 3, topic: 'Erasure Coding: Reed–Solomon k+m and Local Reconstruction Codes',
  kind: 'graph',
  title: 'RS(6,3) across three AZs: encode, lose an AZ, still read',
  desc: 'Reed–Solomon splits an object into k=6 data fragments and computes m=3 parity fragments. Any 6 of the 9 rebuild the object, so placing 3 per AZ survives a whole-AZ outage at 1.5x storage instead of 3x.',
  groups: [
    { id: 'aza', label: 'AZ a', x: 4, y: 0, w: 3, h: 1, color: 'blue' },
    { id: 'azb', label: 'AZ b', x: 4, y: 2, w: 3, h: 1, color: 'blue' },
    { id: 'azc', label: 'AZ c', x: 4, y: 4, w: 3, h: 1, color: 'purple' },
  ],
  nodes: [
    { id: 'client', label: 'Client', sub: '6 MiB object', icon: '💻', x: 0, y: 2, color: 'gray', info: 'Writes and reads whole objects. Erasure coding is invisible to it apart from latency.' },
    { id: 'codec', label: 'RS codec', sub: 'encode / decode', x: 2, y: 2, color: 'orange', info: 'Reed–Solomon arithmetic over a Galois field, accelerated with SIMD. Encoding computes m parity fragments from k data fragments; decoding solves for any missing fragments from any k survivors.' },
    { id: 'd1', label: 'D1', sub: 'data 1 MiB', x: 4, y: 0, color: 'green', info: 'Data fragments are plain slices of the object (a systematic code), so a healthy read just concatenates D1 to D6 with no decoding.' },
    { id: 'd2', label: 'D2', sub: 'data 1 MiB', x: 5, y: 0, color: 'green' },
    { id: 'd3', label: 'D3', sub: 'data 1 MiB', x: 6, y: 0, color: 'green' },
    { id: 'd4', label: 'D4', sub: 'data 1 MiB', x: 4, y: 2, color: 'green', exit: 5 },
    { id: 'd5', label: 'D5', sub: 'data 1 MiB', x: 5, y: 2, color: 'green', exit: 5 },
    { id: 'd6', label: 'D6', sub: 'data 1 MiB', x: 6, y: 2, color: 'green', exit: 5 },
    { id: 'p1', label: 'P1', sub: 'parity 1 MiB', x: 4, y: 4, color: 'purple', info: 'Parity fragments are linear combinations of all six data fragments. Unlike RAID 5 XOR parity, three independent parities let the code survive any three losses.' },
    { id: 'p2', label: 'P2', sub: 'parity 1 MiB', x: 5, y: 4, color: 'purple' },
    { id: 'p3', label: 'P3', sub: 'parity 1 MiB', x: 6, y: 4, color: 'purple' },
  ],
  edges: [
    { from: 'client', to: 'codec', label: 'PUT / GET' },
    { from: 'codec', to: 'd1' },
    { from: 'codec', to: 'd4' },
    { from: 'codec', to: 'p1' },
  ],
  steps: [
    { caption: 'The client PUTs a 6 MiB object. The storage front end hands it to the Reed–Solomon codec.', flows: [{ from: 'client', to: 'codec', label: '6 MiB' }] },
    { caption: 'The object is cut into k=6 data fragments of 1 MiB. They are stored as-is, so normal reads need no decoding at all.', flows: [{ from: 'codec', to: 'd1', label: 'D1-D3' }, { from: 'codec', to: 'd4', label: 'D4-D6' }], active: ['d2', 'd3', 'd5', 'd6'] },
    { caption: 'The codec computes m=3 parity fragments. Total stored is 9 MiB, an overhead of 1.5x, versus 18 MiB for 3x replication, which tolerates only 2 losses.', flows: [{ from: 'codec', to: 'p1', label: 'P1-P3' }], active: ['p2', 'p3'] },
    { caption: 'Placement is what makes the maths real: 3+3+3 across three AZs means losing any whole AZ removes at most m=3 fragments. RS(10,4) spread 5+5+4 would not survive an AZ loss.', active: ['aza', 'azb', 'azc', 'd1', 'd2', 'd3', 'd4', 'd5', 'd6', 'p1', 'p2', 'p3'] },
    { caption: 'AZ b goes down and D4 to D6 are unavailable. No data is lost: 6 of the 9 fragments survive, exactly the k needed.', active: ['azb', 'd1', 'd2', 'd3', 'p1', 'p2', 'p3'] },
    { caption: 'A degraded read fetches the 6 surviving fragments (D1-D3, P1-P3) and solves for the missing data. Cost: extra CPU, cross-AZ traffic and higher latency until repair finishes.', flows: [{ from: 'd1', to: 'codec', label: 'D1-D3' }, { from: 'p1', to: 'codec', label: 'P1-P3' }], active: ['d2', 'd3', 'p2', 'p3'] },
    { caption: 'The client receives the full object. It cannot tell a degraded read from a normal one, apart from latency.', flows: [{ from: 'codec', to: 'client', label: '6 MiB' }] },
    { caption: 'Repair is EC\'s main cost: rebuilding one lost 1 MiB fragment reads k=6 MiB over the network, versus 1 MiB with replication. Azure\'s LRC adds local parities so a single failure reads 6 fragments instead of 12. EC suits large immutable data; small hot objects often stay replicated.', active: ['codec', 'd1', 'p1'] },
  ],
});

registerDiagram({
  id: 'stor-checksum-scrub',
  roadmap: 'storage', module: 3, topic: 'Checksums, Silent Data Corruption and Scrubbing',
  kind: 'graph',
  title: 'End-to-end checksums: detect bit rot, self-heal, scrub cold data',
  desc: 'A disk can return wrong data without any I/O error. Follow one read of a rotted block through a checksumming file system (ZFS, Ceph BlueStore), then see why scrubbing must read data that nobody else reads.',
  groups: [
    { id: 'host', label: 'Storage host', x: 2, y: 0, w: 1, h: 5, color: 'blue' },
    { id: 'mirror', label: 'Mirror / replicas', x: 4, y: 0, w: 1, h: 3, color: 'green' },
  ],
  nodes: [
    { id: 'app', label: 'Application', sub: 'read block 9', icon: '🧑‍💻', x: 0, y: 1, color: 'gray', info: 'The application only sees a successful read or an error. Without end-to-end checksums it would happily consume corrupted bytes and maybe write them back, spreading the damage to replicas and backups.' },
    { id: 'fs', label: 'ZFS / Ceph OSD', sub: 'checksum in parent', x: 2, y: 1, color: 'blue', info: 'ZFS stores each block\'s checksum in its parent block pointer, forming a Merkle tree up to the uberblock. Ceph BlueStore keeps crc32c per block in its RocksDB metadata. Either way the checksum is not stored inside the block it protects.' },
    { id: 'scrub', label: 'Scrubber', sub: 'scrub / deep-scrub', x: 2, y: 4, color: 'purple', info: 'A background job that reads every block of every copy and verifies it, typically weekly or monthly and throttled so client I/O is not starved. Ceph runs light scrubs daily (metadata) and deep scrubs weekly (full data).' },
    { id: 'diskA', label: 'Copy A', sub: 'disk 1: bit rot', x: 4, y: 0, shape: 'db', color: 'red', info: 'Media decay, a firmware bug, or a misdirected write has changed the data. The drive ECC did not catch it, so the read completes without error. Enterprise studies found latent sector errors on a few percent of drives per year.' },
    { id: 'diskB', label: 'Copy B', sub: 'disk 2: good', x: 4, y: 2, shape: 'db', color: 'green', info: 'The second copy of the mirror (or the parity / other replicas). Redundancy only helps if you can tell which copy is correct, which is what the checksum provides.' },
    { id: 'raid', label: 'Plain RAID 1', sub: 'knows only "differ"', x: 6, y: 1, ghost: true, color: 'gray', info: 'A classic mirror without checksums returns whichever copy it reads. During a consistency check (md "check") it can only count mismatches (mismatch_cnt); it cannot tell which side is right.' },
    { id: 'alert', label: 'Alerts', sub: 'CKSUM error counters', x: 0, y: 4, color: 'orange', info: 'zpool status shows READ, WRITE and CKSUM counters per device; Ceph raises OSD_SCRUB_ERRORS and PG_DAMAGED health warnings. Export them to monitoring and page on growth.' },
  ],
  edges: [
    { from: 'app', to: 'fs', label: 'read()' },
    { from: 'fs', to: 'diskA' },
    { from: 'fs', to: 'diskB' },
    { from: 'diskB', to: 'diskA', label: 'repair' },
    { from: 'scrub', to: 'diskA' },
    { from: 'scrub', to: 'diskB' },
    { from: 'scrub', to: 'alert', label: 'report errors' },
  ],
  steps: [
    { caption: 'The application reads block 9. The file system already holds the expected checksum in the parent block pointer (ZFS) or in BlueStore metadata (Ceph): stored apart from the data it protects.', flows: [{ from: 'app', to: 'fs', label: 'read blk 9' }] },
    { caption: 'It reads copy A. The disk returns the data with no I/O error: the drive ECC missed a flipped bit, or a misdirected write put another block here. Only an end-to-end check can notice.', flows: [{ from: 'fs', to: 'diskA', label: 'read copy A' }] },
    { caption: 'Verification fails: the computed checksum does not match the parent pointer. A plain RAID 1 would have returned the bad bytes, or during a check would only know that the copies differ, not which one is right.', active: ['fs', 'diskA', 'raid'] },
    { caption: 'The file system reads copy B (or reconstructs from RAID-Z parity or other Ceph replicas) and verifies it: the checksum matches, so B is known to be good.', flows: [{ from: 'fs', to: 'diskB', label: 'read copy B' }] },
    { caption: 'Self-heal: the good data goes to the application and is rewritten over copy A. The CKSUM counter for disk 1 increments. The application never saw the corruption.', flows: [{ from: 'diskB', to: 'diskA', label: 'rewrite A' }, { from: 'fs', to: 'app', label: 'good data' }] },
    { caption: 'Cold data may never be read by any application, so its rot stays hidden. A scrub reads every block on every copy and verifies it while redundancy still exists: zpool scrub, ceph pg deep-scrub, md check.', flows: [{ from: 'scrub', to: 'diskA', label: 'verify all' }, { from: 'scrub', to: 'diskB', label: 'verify all' }] },
    { caption: 'Scrub results feed alerts. Rising checksum errors on one disk predict its failure, so replace it early. Errors across many disks point to a controller, cable, RAM or firmware problem instead.', flows: [{ from: 'scrub', to: 'alert', label: '3 CKSUM errors' }] },
    { caption: 'Without scrubbing, latent errors surface during a rebuild, when the only other copy is already gone: that is how one disk failure becomes data loss. Checksums plus regular scrubs are a precondition for any durability claim.', active: ['diskA', 'diskB', 'scrub', 'raid'] },
  ],
});

