registerDiagram({
  id: 'stor-inode-path-lookup',
  roadmap: 'storage', module: 4, topic: 'Inodes, Directories, Blocks and Extents',
  kind: 'graph',
  title: 'open("/home/ann/notes.txt"): names, inodes and extents',
  desc: 'A path is resolved one component at a time: inode, then directory data, then the next inode. Names live only in directories, and the inode points at the data through extents. This is also why hard links and deleted-but-open files behave as they do.',
  nodes: [
    { id: 'proc', label: 'open()', sub: '/home/ann/notes.txt', icon: '🧑‍💻', x: 0, y: 0, color: 'gray', info: 'Path resolution happens in the kernel VFS. Hot paths are served from the dentry and inode caches in RAM; the disk walk below happens on a cache miss.' },
    { id: 'ino2', label: 'Inode 2', sub: 'root dir → block 9', x: 2, y: 0, color: 'blue', info: 'In ext4 the root directory is always inode 2. Each directory is just a file whose data blocks contain directory entries.' },
    { id: 'dir9', label: 'Dir block 9', sub: 'home → inode 11', x: 4, y: 0, color: 'purple', info: 'A directory entry is (name, inode number, file type). Small directories are linear lists; large ext4 directories use a hashed HTree index so lookup stays fast with millions of entries.' },
    { id: 'walk', label: 'Repeat per name', sub: 'home, then ann', x: 6, y: 0, ghost: true, color: 'gray', info: 'Each path component costs an inode read, a permission check (execute permission on every directory) and a directory lookup. Deep paths on a cold cache mean many small random reads.' },
    { id: 'dirAnn', label: 'Dir block 77', sub: 'notes.txt → 1234', x: 6, y: 2, color: 'purple', info: 'The directory /home/ann maps the name notes.txt to inode 1234. Rename within one file system just edits directory entries, which is why it is atomic and does not copy data.' },
    { id: 'ino', label: 'Inode 1234', sub: 'mode, size, links', x: 4, y: 2, color: 'blue', info: 'Holds type, permissions, owner, size, atime/mtime/ctime, link count and the extent tree. It does not contain the file name. ext4 fixes the number of inodes at mkfs time: run out of them (df -i) and you get "No space left on device" with free blocks.' },
    { id: 'ext', label: 'Extent tree', sub: '(0, 5000, 256)', x: 2, y: 2, color: 'teal', info: 'Each extent is (logical start, physical start, length). One entry covers up to 128 MiB of contiguous blocks in ext4. Classic block maps needed one pointer per 4 KiB block plus indirect blocks.' },
    { id: 'data', label: 'Data blocks', sub: '5000-5255 (1 MiB)', x: 0, y: 2, shape: 'db', color: 'green', info: '256 contiguous 4 KiB blocks. Delayed allocation picks these at writeback time, so the file system can choose one large run instead of scattered blocks.' },
    { id: 'link', label: 'Dir block 88', sub: 'report.txt → 1234', x: 4, y: 4, color: 'orange', enter: 8, info: 'Created by ln /home/ann/notes.txt /srv/report.txt. A hard link is just a second directory entry for the same inode, so it only works within one file system. A symlink, by contrast, is a separate small file that stores a path.' },
  ],
  edges: [
    { from: 'proc', to: 'ino2', label: 'start at /' },
    { from: 'ino2', to: 'dir9', label: 'read dir' },
    { from: 'dir9', to: 'walk', label: 'inode 11' },
    { from: 'walk', to: 'dirAnn' },
    { from: 'dirAnn', to: 'ino', label: 'inode 1234' },
    { from: 'ino', to: 'ext' },
    { from: 'ext', to: 'data', label: 'map' },
    { from: 'link', to: 'ino', label: 'same inode' },
  ],
  steps: [
    { caption: 'Resolution starts at the root inode (inode 2 in ext4), or at the current directory for a relative path. The kernel tries the dentry cache first; on a miss it reads from disk.', flows: [{ from: 'proc', to: 'ino2', label: 'lookup /' }] },
    { caption: 'A directory is a file. The root inode points at its data block, which holds (name → inode number) entries.', flows: [{ from: 'ino2', to: 'dir9', label: 'read block 9' }] },
    { caption: 'Looking up "home" in that block gives inode 11. Nothing so far has mentioned notes.txt: every component needs its own inode read and directory search.', flows: [{ from: 'dir9', to: 'walk', label: 'home = 11' }] },
    { caption: 'The same two hops repeat for "ann": read inode 11, read its directory data, find ann. The kernel also checks execute permission on each directory along the way.', flows: [{ from: 'walk', to: 'dirAnn', label: 'ann = 57' }] },
    { caption: 'The directory /home/ann maps notes.txt to inode 1234. The name exists only here, in the parent directory, never in the inode itself.', flows: [{ from: 'dirAnn', to: 'ino', label: 'inode 1234' }] },
    { caption: 'The inode holds all the metadata (mode, owner, size, timestamps, link count) and the root of its extent tree.', flows: [{ from: 'ino', to: 'ext', label: 'extents' }] },
    { caption: 'One extent (logical 0, physical 5000, length 256) describes the whole 1 MiB file. A block map would need 256 pointers; a 1 GiB file needs a handful of extents instead of 262,144 pointers.', flows: [{ from: 'ext', to: 'data', label: 'read 1 MiB' }] },
    { caption: 'ln /home/ann/notes.txt /srv/report.txt adds a second directory entry pointing at the same inode, and the link count becomes 2. Both names are equally "the" file.', flows: [{ from: 'link', to: 'ino', label: 'links=2' }] },
    { caption: 'rm only removes a directory entry and decrements the link count. Blocks are freed when the count reaches 0 and no process holds the file open, which is why a deleted log still fills the disk (find it with lsof +L1).', active: ['ino', 'link', 'dirAnn', 'data'] },
  ],
});

registerDiagram({
  id: 'stor-journaling-ordered',
  roadmap: 'storage', module: 4, topic: 'Crash Consistency and Journaling',
  kind: 'sequence',
  title: 'ext4 data=ordered: appending one block, then crash recovery',
  desc: 'Appending a block touches the data block, the inode and the block bitmap. A journal makes the metadata update atomic: write intent, commit, then checkpoint. After a crash, committed transactions are replayed and incomplete ones discarded.',
  actors: [
    { id: 'app', label: 'Application', icon: '🧑‍💻', color: 'gray', info: 'Calls write() and fsync(). Journaling protects the file-system structure; only fsync tells the app that its own data is durable.' },
    { id: 'fs', label: 'ext4 + jbd2', sub: 'kernel', color: 'blue', info: 'jbd2 is the journalling layer used by ext4. It groups many metadata changes into one transaction and commits about every 5 seconds (commit=5) or on fsync.' },
    { id: 'data', label: 'Data block', sub: 'final location', color: 'green', info: 'In ordered mode file data is never journaled; it is written once, directly to its final location, before the metadata that references it commits.' },
    { id: 'jnl', label: 'Journal', sub: 'circular log on disk', color: 'orange', info: 'A fixed-size circular area (often 128 MiB to 1 GiB). Writes to it are sequential, which is why journaling is cheap compared with random in-place metadata writes.' },
    { id: 'meta', label: 'Metadata home', sub: 'inode, bitmap', color: 'purple', info: 'The inode table and block bitmap at their real on-disk locations. They are updated later, at checkpoint, from the copies in memory.' },
  ],
  steps: [
    { section: 'Append 4 KiB in data=ordered mode' },
    { from: 'app', to: 'fs', label: 'write() + fsync()', caption: 'The append must update three structures: the new data block, the inode (size and extent) and the block bitmap. A crash between those writes could leak a block or leave the inode pointing at garbage.' },
    { from: 'fs', to: 'data', label: 'write data block', caption: 'Ordered mode writes the data block to its final location first. That way committed metadata can never point at a block full of stale or garbage content.' },
    { from: 'fs', to: 'jnl', label: 'TxBegin + inode + bitmap', caption: 'jbd2 writes copies of the changed metadata blocks (the inode and the bitmap) into the journal, sequentially. Until a commit record follows them, this transaction does not count.' },
    { from: 'fs', to: 'fs', label: 'cache flush', caption: 'A device cache flush (barrier) ensures the data block and journal blocks are on stable storage before the commit record, because drives may reorder writes in their cache.' },
    { from: 'fs', to: 'jnl', label: 'TxCommit', caption: 'The commit block (checksummed, written with FUA) makes the transaction atomic. From this moment the append survives a crash.' },
    { from: 'fs', to: 'app', label: 'fsync returns 0', reply: true, caption: 'Only now does fsync return. Without fsync the application would have no idea when, or whether, the append became durable.' },
    { section: 'Later: checkpoint' },
    { from: 'fs', to: 'meta', label: 'checkpoint inode, bitmap', caption: 'In the background, the metadata is written to its home locations. Once that is done the journal space is released and the log tail moves forward.' },
    { section: 'Power loss, then mount' },
    { from: 'jnl', to: 'fs', label: 'scan journal', reply: true, caption: 'On mount after a crash, jbd2 scans the journal. A transaction with a valid commit block is replayed; one without a commit (crash before TxCommit) is ignored, so the file simply keeps its old size.' },
    { from: 'fs', to: 'meta', label: 'replay committed tx', caption: 'Replay rewrites the full metadata blocks to their home locations. Physical redo is idempotent, so crashing during recovery is safe. This takes seconds, versus hours of fsck on a large unjournaled disk.' },
  ],
});

registerDiagram({
  id: 'stor-fsync-path',
  roadmap: 'storage', module: 4, topic: 'Page Cache, fsync and Durability Pitfalls',
  kind: 'graph',
  title: 'write() vs fsync(): the path from RAM to stable storage',
  desc: 'write() returns as soon as bytes are in the page cache. fsync() pushes them through the file system, block layer and device, and ends with a cache flush. Follow one 4 KiB write and see exactly when it becomes crash-safe.',
  groups: [
    { id: 'kern', label: 'Linux kernel', x: 0, y: 1, w: 4, h: 3, color: 'blue' },
    { id: 'dev', label: 'Storage device', x: 0, y: 4, w: 2, h: 2, color: 'green' },
  ],
  nodes: [
    { id: 'app', label: 'Application', sub: 'write(fd, 4 KiB)', icon: '🧑‍💻', x: 0, y: 0, w: 2, color: 'gray', info: 'From the application\'s point of view write() succeeded. It does not mean the data is on disk.' },
    { id: 'pc', label: 'Page cache', sub: 'dirty pages in RAM', x: 0, y: 1, w: 2, color: 'blue', info: 'All buffered file I/O goes through here. Reads of recently written data are served from RAM. A process crash loses nothing (the kernel owns the pages); a kernel panic or power cut loses every dirty page.' },
    { id: 'fs', label: 'File system', sub: 'allocation + journal', x: 0, y: 2, w: 2, color: 'blue', info: 'Maps file pages to blocks (delayed allocation happens here) and commits metadata through its journal. fsync on ext4 or XFS forces a journal commit for the file\'s metadata.' },
    { id: 'blk', label: 'Block layer + driver', sub: 'merge, queue, NVMe', x: 0, y: 3, w: 2, color: 'blue', info: 'Merges adjacent requests, applies the I/O scheduler (often none for NVMe) and submits commands to per-CPU hardware queues.' },
    { id: 'cache', label: 'Device write cache', sub: 'volatile DRAM', x: 0, y: 4, w: 2, color: 'orange', info: 'Drives acknowledge writes once they reach this cache. Without power-loss protection (PLP) its contents vanish on a power cut, which is why fsync must end with a flush.' },
    { id: 'nand', label: 'NAND / platters', sub: 'stable storage', x: 0, y: 5, w: 2, shape: 'db', color: 'green', info: 'Only data here survives a power cut. Enterprise SSDs with PLP capacitors can treat their cache as stable, which makes fsync both safe and fast (tens of microseconds instead of milliseconds).' },
    { id: 'flush', label: 'Flusher threads', sub: 'writeback ~30 s', x: 3, y: 1, color: 'purple', info: 'Kernel writeback workers flush dirty pages older than vm.dirty_expire_centisecs (30 s) or when dirty memory exceeds vm.dirty_background_ratio. If dirty pages hit vm.dirty_ratio, writers are throttled.' },
  ],
  edges: [
    { from: 'app', to: 'pc' },
    { from: 'flush', to: 'pc', label: 'wake' },
    { from: 'pc', to: 'fs' },
    { from: 'fs', to: 'blk' },
    { from: 'blk', to: 'cache' },
    { from: 'cache', to: 'nand' },
  ],
  steps: [
    { caption: 'write() copies 4 KiB into the page cache, marks the page dirty and returns in microseconds. Nothing has touched the disk yet.', flows: [{ from: 'app', to: 'pc', label: 'write()' }] },
    { caption: 'The data now lives only in RAM. If the process crashes it is safe, because the kernel owns the page. If the kernel panics or the power fails, it is gone.', active: ['pc'] },
    { caption: 'Without fsync, flusher threads write it back eventually: after about 30 s, or sooner under memory pressure. The order is up to the kernel, so a commit record may reach disk before the data it describes.', flows: [{ from: 'flush', to: 'pc', label: 'expire 30 s' }, { from: 'pc', to: 'fs', label: 'writeback' }] },
    { caption: 'fsync(fd) instead forces the issue now: the file\'s dirty pages are written out and its metadata is committed through the journal. fdatasync skips metadata not needed to read the data, such as mtime.', flows: [{ from: 'app', to: 'pc', label: 'fsync(fd)' }, { from: 'pc', to: 'fs', label: 'dirty pages' }] },
    { caption: 'The file system turns pages into block I/O plus a journal commit, and the block layer queues NVMe write commands.', flows: [{ from: 'fs', to: 'blk', label: 'bios + journal' }, { from: 'blk', to: 'cache', label: 'NVMe WRITE' }] },
    { caption: 'The device acknowledges once data is in its volatile cache, which is not yet durable. So fsync finishes with a FLUSH (or FUA writes), forcing the cache onto stable media.', flows: [{ from: 'blk', to: 'cache', label: 'FLUSH' }, { from: 'cache', to: 'nand', label: 'persist' }] },
    { caption: 'Only now does fsync return 0. That round trip costs milliseconds on drives without PLP, which is why databases batch many commits into one fsync (group commit).', flows: [{ from: 'cache', to: 'blk', label: 'done' }, { from: 'blk', to: 'fs', label: 'done' }, { from: 'fs', to: 'pc', label: 'done' }, { from: 'pc', to: 'app', label: 'fsync = 0' }] },
    { caption: 'Pitfalls: for a new file also fsync the parent directory; atomic replace is write temp, fsync, rename, fsync dir. After an fsync error the pages may be marked clean (fsyncgate), so PostgreSQL PANICs and replays WAL.', active: ['pc', 'fs', 'app'] },
  ],
});

registerDiagram({
  id: 'stor-cow-snapshot',
  roadmap: 'storage', module: 4, topic: 'Copy-on-Write and Snapshots',
  kind: 'graph',
  title: 'Copy-on-write: overwrite one block, take snapshots for free',
  desc: 'A CoW file system (ZFS, Btrfs) never overwrites live blocks. A change writes a new block, new copies of every parent up to the root, then flips one root pointer atomically. A snapshot is just a kept reference to an old root.',
  nodes: [
    { id: 'snap', label: 'Snapshot @mon', sub: 'keeps root v1', icon: '📸', x: 0, y: 0, color: 'purple', enter: 2, info: 'Taking a snapshot copies no data: it records the current root and stops the blocks under it from being freed. Snapshots are O(1) in time and initially free in space.' },
    { id: 'ubOld', label: 'Uberblock txg 41', sub: 'live root pointer', x: 3, y: 0, color: 'blue', exit: 6, info: 'The single entry point to the whole tree (Btrfs: superblock). ZFS keeps a ring of uberblocks and uses the newest valid one at import.' },
    { id: 'ubNew', label: 'Uberblock txg 42', sub: 'atomic switch', x: 5, y: 0, color: 'blue', enter: 6, info: 'Written in one atomic step once all new blocks are on disk. A crash before this write leaves txg 41 intact; after it, txg 42 is live. There is no in-between state, so no journal and no fsck.' },
    { id: 'r1', label: 'Root v1', x: 2, y: 1, color: 'teal', info: 'Every pointer in the tree also stores the checksum of the block it points to, so the tree is a Merkle tree: a corrupted block is detected on read and can be repaired from a mirror or parity.' },
    { id: 'r2', label: 'Root v2', x: 4.5, y: 1, color: 'teal', enter: 5 },
    { id: 'm1', label: 'Meta M1', x: 0.5, y: 3, color: 'gray', info: 'An indirect (metadata) block. It did not change, so the new root simply points at the same block: unchanged subtrees are shared between versions.' },
    { id: 'm2', label: 'Meta M2', x: 3.5, y: 3, color: 'gray' },
    { id: 'm2n', label: 'Meta M2\'', x: 5.5, y: 3, color: 'orange', enter: 4, info: 'A new copy of M2 that points at C\' instead of C, and still at the unchanged D.' },
    { id: 'a', label: 'A', x: 0, y: 5, color: 'green' },
    { id: 'b', label: 'B', x: 1, y: 5, color: 'green' },
    { id: 'c', label: 'C (old)', x: 3, y: 5, color: 'green', info: 'The old version of the block. It is still referenced by the snapshot, so it cannot be freed: deleting or overwriting data on a snapshotted dataset may not free any space.' },
    { id: 'd', label: 'D', x: 4, y: 5, color: 'green' },
    { id: 'cn', label: 'C\' (new)', x: 6, y: 5, color: 'orange', enter: 3, info: 'The new data, written to free space elsewhere on disk. For random overwrites (databases, VM images) this scatters a file over time, so match recordsize to the DB page size.' },
  ],
  edges: [
    { from: 'snap', to: 'r1' },
    { from: 'ubOld', to: 'r1' },
    { from: 'ubNew', to: 'r2' },
    { from: 'r1', to: 'm1' },
    { from: 'r1', to: 'm2' },
    { from: 'r2', to: 'm1' },
    { from: 'r2', to: 'm2n' },
    { from: 'm1', to: 'a' },
    { from: 'm1', to: 'b' },
    { from: 'm2', to: 'c' },
    { from: 'm2', to: 'd' },
    { from: 'm2n', to: 'd' },
    { from: 'm2n', to: 'cn' },
  ],
  steps: [
    { caption: 'The live file system is a tree: the uberblock points at the root, the root at metadata blocks, and those at data blocks A to D. Every pointer also stores its child\'s checksum.', active: ['ubOld', 'r1', 'm1', 'm2', 'a', 'b', 'c', 'd', 'ubOld>r1', 'r1>m1', 'r1>m2', 'm1>a', 'm1>b', 'm2>c', 'm2>d'] },
    { caption: 'zfs snapshot pool/db@mon records a reference to root v1. No data is copied, so it is instant whatever the size of the dataset.', flows: [{ from: 'snap', to: 'r1', label: 'reference' }] },
    { caption: 'The app overwrites block C. CoW never writes in place: the new contents C\' go to free space elsewhere, and the old C stays untouched.', active: ['cn', 'c'] },
    { caption: 'M2 points at C, so it must change too. A new copy M2\' is written that points at C\' and still at the unchanged D.', flows: [{ from: 'm2n', to: 'cn', label: 'new ptr' }, { from: 'm2n', to: 'd', label: 'shared' }] },
    { caption: 'The change ripples to the top: a new root v2 points at the unchanged M1 (shared) and the new M2\'. Only the blocks on the path from C to the root were rewritten.', flows: [{ from: 'r2', to: 'm1', label: 'shared' }, { from: 'r2', to: 'm2n', label: 'new' }] },
    { caption: 'One atomic write of a new uberblock (txg 42) makes v2 live. A crash just before leaves the complete old tree; just after, the complete new one. The on-disk state is always consistent.', flows: [{ from: 'ubNew', to: 'r2', label: 'txg 42' }] },
    { caption: 'The snapshot still reaches root v1, M2 and the old C, so those blocks are kept. This is why deleting files on a snapshotted dataset frees little space until old snapshots are destroyed.', active: ['snap', 'r1', 'm2', 'c', 'snap>r1', 'r1>m2', 'm2>c'] },
    { caption: 'Incremental replication is exact: zfs send -i @mon streams only blocks born after txg 41 (root v2, M2\' and C\'), with no need to scan or diff the whole dataset.', active: ['r2', 'm2n', 'cn', 'ubNew'] },
  ],
});

