registerDiagram({
  id: 'stor-bplus-split',
  roadmap: 'storage', module: 5, topic: 'B-Tree and B+Tree Internals',
  kind: 'graph',
  title: 'B+tree insert: leaf split cascades into a root split',
  desc: 'Nodes here hold at most 2 keys (a real 16 KiB page holds about 1,000). Inserting 45 overflows a leaf, the split pushes a separator up, the root overflows too, and the tree grows a level. Press Play to watch it split.',
  nodes: [
    { id: 'ins', label: 'INSERT 45', shape: 'pill', x: 6, y: 0, color: 'gray', exit: 5, info: 'Every insert first descends from the root to the one leaf whose key range contains the new key.' },
    { id: 'newRoot', label: 'Root [40]', x: 3, y: 0, color: 'purple', enter: 5, info: 'The new root. B-trees grow at the top, never at the bottom, so every leaf stays at the same depth and the tree stays balanced.' },
    { id: 'oldRoot', label: 'Root [20 | 40]', x: 3, y: 1, color: 'blue', exit: 5, info: 'An internal node holds separator keys and child pointers only. Keys < 20 go left, 20 to 39 go to the middle child, and 40 or more go right.' },
    { id: 'intL', label: 'Inner [20]', x: 1, y: 2, color: 'blue', enter: 5 },
    { id: 'intR', label: 'Inner [45]', x: 4.5, y: 2, color: 'blue', enter: 5 },
    { id: 'l1', label: 'Leaf [5 | 10]', x: 0, y: 4, color: 'green', info: 'Leaves hold the keys plus the row (InnoDB clustered index) or a row pointer (PostgreSQL ctid). They are linked left to right for range scans.' },
    { id: 'l2', label: 'Leaf [20 | 30]', x: 2, y: 4, color: 'green' },
    { id: 'l3', label: 'Leaf [40 | 50]', x: 4.5, y: 4, color: 'green', exit: 3, info: 'Already full (2 keys), so inserting 45 overflows it.' },
    { id: 'l3a', label: 'Leaf [40]', x: 3.5, y: 5, color: 'orange', enter: 3, info: 'Left half after the split. Both halves are now half full: random-key inserts leave pages around 50 to 70 percent full on average.' },
    { id: 'l3b', label: 'Leaf [45 | 50]', x: 5.5, y: 5, color: 'orange', enter: 3, info: 'A newly allocated page holding the upper half. Its first key, 45, is copied up as the separator: in a B+tree the leaf keeps it.' },
  ],
  edges: [
    { from: 'ins', to: 'oldRoot' },
    { from: 'oldRoot', to: 'l1' },
    { from: 'oldRoot', to: 'l2' },
    { from: 'oldRoot', to: 'l3' },
    { from: 'newRoot', to: 'intL' },
    { from: 'newRoot', to: 'intR' },
    { from: 'intL', to: 'l1' },
    { from: 'intL', to: 'l2' },
    { from: 'intR', to: 'l3a' },
    { from: 'intR', to: 'l3b' },
    { from: 'l1', to: 'l2', dashed: true },
    { from: 'l2', to: 'l3', dashed: true },
    { from: 'l2', to: 'l3a', dashed: true },
    { from: 'l3a', to: 'l3b', dashed: true },
  ],
  steps: [
    { caption: 'INSERT 45 starts at the root. 45 is at least 40, so the search follows the rightmost child. Upper levels are almost always cached, so a lookup costs about one disk read.', flows: [{ from: 'ins', to: 'oldRoot', label: 'key 45' }] },
    { caption: 'The target leaf [40 | 50] is already full. Unlike an LSM-tree, a B+tree must update this exact page in place.', flows: [{ from: 'oldRoot', to: 'l3', label: 'key 45' }] },
    { caption: 'Leaf split: a new page is allocated; [40] stays left, [45 | 50] moves right, and the sibling links are rewired. Several pages change, and every change is logged to the WAL first.', active: ['l3a', 'l3b', 'l2>l3a', 'l3a>l3b'] },
    { caption: 'The separator 45 is copied up into the parent. The root would now need three keys [20 | 40 | 45], but it holds at most two, so it overflows as well.', flows: [{ from: 'l3b', to: 'oldRoot', label: 'separator 45' }] },
    { caption: 'The root splits into [20] and [45], and the middle key 40 moves up into a brand-new root. Height grows from 2 to 3. This cascade is the only way a B-tree gets taller, which keeps all leaves at equal depth.', flows: [{ from: 'newRoot', to: 'intL', label: '< 40' }, { from: 'newRoot', to: 'intR', label: '>= 40' }] },
    { caption: 'Range scans (WHERE k BETWEEN 10 AND 50) walk the leaf chain sideways without going back up the tree. That is a key B+tree advantage over hash indexes.', flows: [{ from: 'l1', to: 'l2', label: 'scan' }, { from: 'l2', to: 'l3a', label: 'scan' }, { from: 'l3a', to: 'l3b', label: 'scan' }] },
    { caption: 'With fan-out 1,000, 3 to 4 levels index a billion rows. Random keys (UUIDv4) split pages all over the index; sequential keys (BIGSERIAL, UUIDv7) only append to the rightmost leaf, giving dense pages and a small hot working set.', active: ['newRoot', 'intL', 'intR', 'l3a', 'l3b'] },
  ],
});

registerDiagram({
  id: 'stor-lsm-write-read',
  roadmap: 'storage', module: 5, topic: 'LSM-Trees: Memtables, SSTables, Compaction and Bloom Filters',
  kind: 'graph',
  title: 'LSM-tree: write path, flush, compaction and read path',
  desc: 'An LSM-tree turns random writes into sequential ones: log, buffer in memory, flush sorted immutable files, and merge them in the background. Reads pay for it by checking several places, and Bloom filters keep that cheap.',
  groups: [
    { id: 'mem', label: 'Memory', x: 2, y: 1, w: 5, h: 1, color: 'blue' },
    { id: 'disk', label: 'Disk', x: 2, y: 3, w: 5, h: 3, color: 'green' },
  ],
  nodes: [
    { id: 'client', label: 'Client', sub: 'put / get', icon: '💻', x: 0, y: 1, color: 'gray', info: 'Writes are blind: an LSM put never reads the old value first, unlike a B-tree update that must find and rewrite the page.' },
    { id: 'memt', label: 'Memtable', sub: 'skiplist, sorted', x: 2, y: 1, color: 'blue', info: 'An in-memory sorted structure (a skiplist in RocksDB and Cassandra). RocksDB\'s default write_buffer_size is 64 MiB.' },
    { id: 'imm', label: 'Frozen memtable', sub: 'read-only, flushing', x: 4, y: 1, color: 'blue', enter: 3, exit: 6, info: 'When a memtable fills it becomes immutable and a fresh one takes new writes, so flushing never blocks writers (unless flushes fall behind and write stalls kick in).' },
    { id: 'bloom', label: 'Bloom filters', sub: '10 bits/key, 1% FP', x: 6, y: 1, color: 'purple', info: 'One per SSTable, cached in memory. "No" is certain; "maybe" costs a disk read. About 10 bits per key gives roughly a 1 percent false-positive rate. Bloom filters do not help range scans.' },
    { id: 'wal', label: 'WAL', sub: 'append-only log', x: 2, y: 3, shape: 'db', color: 'orange', info: 'The commit log makes the memtable durable. After a crash the memtable is rebuilt by replaying it. A WAL segment is deleted once its memtable has been flushed.' },
    { id: 'sst1', label: 'L0 SSTable #1', sub: 'sorted, immutable', x: 4, y: 3, color: 'teal', enter: 4, exit: 7, info: 'Data blocks sorted by key, a block index and a Bloom filter. Written once, sequentially, never modified. L0 files come straight from flushes, so their key ranges overlap.' },
    { id: 'sst2', label: 'L0 SSTable #2', sub: 'overlaps #1', x: 5, y: 3, color: 'teal', enter: 5, exit: 7 },
    { id: 'l1', label: 'L1 sorted run', sub: 'non-overlapping files', x: 5, y: 5, w: 2, color: 'green', enter: 6, info: 'With leveled compaction every level from L1 down is one sorted run split into files with disjoint key ranges, and each level is about 10x larger than the previous. A point read checks at most one file per level.' },
  ],
  edges: [
    { from: 'client', to: 'wal', label: 'append' },
    { from: 'client', to: 'memt' },
    { from: 'memt', to: 'imm', label: 'freeze' },
    { from: 'memt', to: 'bloom', curve: -80 },
    { from: 'imm', to: 'sst1', label: 'flush' },
    { from: 'imm', to: 'sst2' },
    { from: 'sst1', to: 'l1' },
    { from: 'sst2', to: 'l1' },
    { from: 'bloom', to: 'l1' },
  ],
  steps: [
    { caption: 'put(k, v) is first appended to the WAL: one sequential write, made durable with fsync (often group-committed across many writers).', flows: [{ from: 'client', to: 'wal', label: 'put k=v' }] },
    { caption: 'Then it is inserted into the in-memory memtable and acknowledged. No random disk I/O and no read-before-write: this is why LSM engines absorb heavy write loads.', flows: [{ from: 'client', to: 'memt', label: 'insert' }] },
    { caption: 'When the memtable reaches its size limit (64 MiB by default in RocksDB) it is frozen and a new memtable takes writes.', flows: [{ from: 'memt', to: 'imm', label: 'freeze' }] },
    { caption: 'The frozen memtable is written out in key order as an SSTable, one large sequential write. Its WAL segment can then be deleted.', flows: [{ from: 'imm', to: 'sst1', label: 'flush' }] },
    { caption: 'More flushes create more L0 files. Their key ranges overlap, so a read may have to check every L0 file, and too many of them makes reads slow.', flows: [{ from: 'imm', to: 'sst2', label: 'flush' }] },
    { caption: 'Compaction merge-sorts L0 into L1, keeping only the newest version of each key and dropping tombstones that are old enough. Rewriting data level after level is the write amplification: 10 to 30x for leveled compaction.', flows: [{ from: 'sst1', to: 'l1', label: 'merge' }, { from: 'sst2', to: 'l1', label: 'merge' }] },
    { caption: 'get(k) checks the newest data first: the memtable (and any frozen memtables). A hit returns immediately, and the newest version always wins.', flows: [{ from: 'client', to: 'memt', label: 'get k' }] },
    { caption: 'On a miss, each SSTable\'s Bloom filter is consulted in memory. A "definitely not here" answer skips that file without any disk read.', flows: [{ from: 'memt', to: 'bloom', label: 'not in memory' }] },
    { caption: 'Only files whose filter says "maybe" are read: index block, then one data block. With leveled compaction that is about one file per level, so a point read costs about 1 to 2 disk reads.', flows: [{ from: 'bloom', to: 'l1', label: 'read 1 block' }] },
    { caption: 'Compaction strategy sets the trade-off. Leveled: low space and read amp, high write amp. Size-tiered: cheap writes, up to 2x space. Time-window: drop whole files when the TTL expires, ideal for time series.', active: ['l1', 'bloom', 'wal', 'memt'] },
  ],
});

registerDiagram({
  id: 'stor-wal-recovery',
  roadmap: 'storage', module: 5, topic: 'Write-Ahead Logging and Crash Recovery',
  kind: 'sequence',
  title: 'WAL: commit without writing data pages, then ARIES-style recovery',
  desc: 'A transaction commits when its log records are durable; data pages are written later, in any order. After a crash, recovery replays the log from the last checkpoint and removes the effects of transactions that never committed.',
  actors: [
    { id: 'tx', label: 'Transactions', sub: 'T1 commits, T2 not', icon: '🧑‍💻', color: 'gray', info: 'T1 updates a row and commits. T2 updates another row and is still running when the server crashes.' },
    { id: 'bp', label: 'Buffer pool', sub: 'dirty pages in RAM', color: 'blue', info: 'Pages are modified in memory. Every page header stores the LSN of the last log record applied to it (pageLSN).' },
    { id: 'wal', label: 'WAL', sub: 'sequential, LSNs', color: 'orange', info: 'Append-only log of changes, each record numbered with a monotonically increasing log sequence number (LSN). PostgreSQL writes 16 MB segments; InnoDB uses a circular redo log.' },
    { id: 'data', label: 'Data files', sub: 'table + index pages', color: 'green', info: 'Written lazily by checkpoints and background writers, in any order, possibly long after commit.' },
    { id: 'rec', label: 'Recovery', sub: 'runs at startup', icon: '🛠️', color: 'purple', info: 'Runs before the database accepts connections. Its duration is bounded by how much WAL has accumulated since the last checkpoint.' },
  ],
  steps: [
    { section: 'Normal operation' },
    { from: 'tx', to: 'bp', label: 'T1 UPDATE (LSN 101)', caption: 'T1 changes a row: the page is modified in the buffer pool and a WAL record with LSN 101 is appended to the in-memory WAL buffer. The page now has pageLSN 101.' },
    { from: 'tx', to: 'wal', label: 'T1 COMMIT: flush to LSN 102', caption: 'Commit appends a commit record (LSN 102) and fdatasyncs the WAL. Group commit lets many transactions share one flush, which is what makes high commit rates possible.' },
    { from: 'wal', to: 'tx', label: 'commit OK', reply: true, caption: 'T1 is durable even though its data page exists only in RAM. Commit cost is one sequential log write, not random page writes.' },
    { from: 'bp', to: 'data', label: 'checkpoint: flush dirty pages', caption: 'A checkpoint writes dirty pages and records a redo start point. WAL rule: a page with pageLSN 101 may reach disk only after the WAL is durable up to 101. PostgreSQL logs a full-page image after each checkpoint to survive torn pages.' },
    { from: 'tx', to: 'bp', label: 'T2 UPDATE (LSN 205)', caption: 'T2 modifies another page and its WAL record may even be flushed by someone else\'s commit, but T2 never writes a commit record.' },
    { from: 'bp', to: 'bp', label: 'power loss', caption: 'The server crashes. The buffer pool is gone: some changed pages reached disk, some did not, and an uncommitted change might be on disk too.' },
    { section: 'Recovery at startup' },
    { from: 'rec', to: 'wal', label: 'analysis from checkpoint', caption: 'Analysis scans the WAL from the last checkpoint to learn which transactions committed (T1) and which were still in flight (T2), and which pages may be dirty.' },
    { from: 'rec', to: 'data', label: 'redo if pageLSN < LSN', caption: 'Redo repeats history: each logged change is reapplied if the page\'s pageLSN shows it is missing. This is idempotent, so a crash during recovery just restarts it.' },
    { from: 'rec', to: 'data', label: 'undo T2', caption: 'Undo removes T2\'s changes. InnoDB rolls them back with undo logs; PostgreSQL skips undo entirely, because T2\'s tuple versions are simply invisible (commit log says aborted) and vacuum removes them later.' },
    { from: 'rec', to: 'tx', label: 'accept connections', caption: 'The database opens. Recovery time is set by checkpoint frequency (checkpoint_timeout, max_wal_size): fewer checkpoints mean less I/O but longer recovery. The same WAL feeds replicas, PITR and CDC.' },
  ],
});

registerDiagram({
  id: 'stor-buffer-pool-page-cache',
  roadmap: 'storage', module: 5, topic: 'Pages, Heap Files and the Buffer Pool',
  kind: 'graph',
  title: 'Buffer pool, OS page cache and disk: where a database page lives',
  desc: 'PostgreSQL caches pages twice (shared_buffers and the kernel page cache); InnoDB bypasses the kernel with O_DIRECT. Follow a read miss, an update, a commit and a checkpoint to see which layer is on the critical path and why sizing differs.',
  groups: [
    { id: 'pgmem', label: 'PostgreSQL shared memory', x: 2, y: 0, w: 1, h: 3, color: 'blue' },
    { id: 'kern', label: 'Linux kernel', x: 4, y: 0, w: 1, h: 1, color: 'purple' },
    { id: 'mysql', label: 'MySQL InnoDB (for contrast)', x: 2, y: 4, w: 5, h: 1, color: 'orange' },
  ],
  nodes: [
    { id: 'q', label: 'Backend', sub: 'query needs page 7', icon: '🔎', x: 0, y: 0, color: 'gray', info: 'One PostgreSQL backend process per connection. It never reads files directly for table data without going through shared_buffers first.' },
    { id: 'sb', label: 'shared_buffers', sub: 'clock-sweep, 25% RAM', x: 2, y: 0, color: 'blue', info: 'Fixed array of 8 KiB buffers plus a hash table from (relation, block) to buffer. Buffers are pinned while in use; eviction uses a clock-sweep with usage counts. Sized to roughly 25% of RAM because the page cache does the rest.' },
    { id: 'wal', label: 'WAL buffers', sub: 'flushed at commit', x: 2, y: 2, color: 'orange', info: 'In-memory ring of WAL records. Commit forces them to disk up to the commit LSN; the WAL writer also flushes them in the background.' },
    { id: 'pc', label: 'OS page cache', sub: 'rest of RAM', x: 4, y: 0, color: 'purple', info: 'The kernel caches file pages in otherwise free memory and writes dirty pages back on its own schedule (vm.dirty_background_ratio, vm.dirty_expire_centisecs) or on fsync. effective_cache_size tells the planner how big it probably is.' },
    { id: 'disk', label: 'Data files', sub: 'NVMe / EBS', x: 6, y: 0, shape: 'db', color: 'green', info: 'Tables and indexes as 1 GB segment files. A random 8 KiB read costs ~0.1 ms on local NVMe and ~0.5 to 1 ms on network block storage.' },
    { id: 'walf', label: 'WAL files', sub: '16 MB segments', x: 6, y: 2, shape: 'db', color: 'orange', info: 'Sequential log on the same or a separate volume. Its fsync latency is your commit latency, which is why WAL often gets its own low-latency volume.' },
    { id: 'ckpt', label: 'Checkpointer', sub: '+ bgwriter', x: 0, y: 2, color: 'purple', info: 'The checkpointer flushes all dirty buffers every checkpoint_timeout or max_wal_size, spreading writes over checkpoint_completion_target (0.9). The background writer trickles out dirty buffers ahead of eviction so backends rarely write themselves.' },
    { id: 'inno', label: 'InnoDB pool', sub: '50-75% of RAM', x: 2, y: 4, color: 'orange', info: 'InnoDB caches pages once, in its own pool, with an LRU split into young and old sublists so a single table scan cannot flush the hot set. Dirty pages are flushed by page cleaner threads, protected by the redo log and doublewrite buffer.' },
    { id: 'idisk', label: 'InnoDB data files', sub: 'ibd tablespaces', x: 6, y: 4, shape: 'db', color: 'green', info: 'With innodb_flush_method = O_DIRECT (the Linux default in MySQL 8.4) data file I/O bypasses the page cache entirely, so RAM is not wasted on a second copy.' },
  ],
  edges: [
    { from: 'q', to: 'sb', label: 'lookup / pin' },
    { from: 'sb', to: 'pc', label: 'read() / write()' },
    { from: 'pc', to: 'disk', label: 'block I/O' },
    { from: 'sb', to: 'wal', label: 'WAL record' },
    { from: 'wal', to: 'walf', label: 'write + fdatasync' },
    { from: 'ckpt', to: 'sb', label: 'flush dirty' },
    { from: 'inno', to: 'idisk', label: 'O_DIRECT, no page cache' },
  ],
  steps: [
    { caption: 'A query needs page 7 of orders. The backend looks it up in shared_buffers and pins it. A hit costs about 100 ns and no system call: this is the hit ratio you watch.', flows: [{ from: 'q', to: 'sb', label: 'page 7?' }] },
    { caption: 'Miss: clock-sweep picks a victim buffer and PostgreSQL calls read(). If the kernel page cache has the page, it is just a memory copy of a few microseconds: the double caching PostgreSQL relies on.', flows: [{ from: 'sb', to: 'pc', label: 'read()' }] },
    { caption: 'Double miss: the kernel reads from the device (about 0.1 ms on NVMe, 0.5 to 1 ms on EBS) and caches the page. EXPLAIN (BUFFERS) reports both cases as "read": it cannot tell a page-cache hit from real I/O.', flows: [{ from: 'pc', to: 'disk', label: 'miss: 8 KiB read' }] },
    { caption: 'An UPDATE changes the page in shared_buffers (now dirty) and appends a WAL record describing the change. Nothing is written to the data file yet.', flows: [{ from: 'q', to: 'sb', label: 'UPDATE row' }, { from: 'sb', to: 'wal', label: 'WAL record' }] },
    { caption: 'COMMIT writes the WAL buffers and fdatasyncs the WAL file. This sequential flush is the only disk work on the commit path; group commit shares it between concurrent transactions.', flows: [{ from: 'wal', to: 'walf', label: 'fdatasync' }] },
    { caption: 'Later the checkpointer (and bgwriter) writes dirty buffers with plain write(). They land in the page cache as dirty kernel pages: not yet durable, and the kernel may write them whenever it likes.', flows: [{ from: 'ckpt', to: 'sb', label: 'flush dirty' }, { from: 'sb', to: 'pc', label: 'write()' }] },
    { caption: 'At the end of the checkpoint PostgreSQL fsyncs every file it touched, and only then may old WAL be recycled. Spreading writes (checkpoint_completion_target = 0.9) avoids an I/O storm at that fsync.', flows: [{ from: 'pc', to: 'disk', label: 'fsync' }], active: ['ckpt'] },
    { caption: 'InnoDB takes the other route: O_DIRECT bypasses the kernel cache, so each page is cached once and the buffer pool gets most of RAM. PostgreSQL 18 adds asynchronous I/O (io_method worker or io_uring) but still reads through the page cache.', flows: [{ from: 'inno', to: 'idisk', label: 'O_DIRECT' }] },
    { caption: 'Sizing follows from this: PostgreSQL shared_buffers about 25% of RAM, the rest left to the page cache; InnoDB buffer pool 50 to 75%. In both, whether the working set fits in RAM matters more than disk speed.', active: ['sb', 'pc', 'inno'] },
  ],
});

registerDiagram({
  id: 'stor-mvcc-visibility',
  roadmap: 'storage', module: 5, topic: 'MVCC, Clustered vs Secondary Indexes',
  kind: 'graph',
  title: 'MVCC in PostgreSQL: one row, three versions, three snapshots',
  desc: 'Each UPDATE writes a new tuple version stamped with xmin and xmax. Every snapshot walks the same version chain and stops at the version it is allowed to see, so readers never block writers. VACUUM can remove a version only when no snapshot needs it.',
  groups: [
    { id: 'heap', label: 'Heap page 0 (row id = 42)', x: 2, y: 0, w: 1.5, h: 5, color: 'green' },
    { id: 'txns', label: 'Concurrent snapshots', x: 5, y: 0, w: 1.5, h: 5, color: 'gray' },
  ],
  nodes: [
    { id: 'idx', label: 'B-tree index', sub: 'key 42 → ctid (0,1)', x: 0, y: 0, color: 'blue', info: 'The index entry points at the first tuple of the chain. With HOT updates (no indexed column changed, room on the same page) the index is not touched again: readers follow the chain inside the page.' },
    { id: 'vac', label: 'VACUUM', sub: 'needs xmin horizon', x: 0, y: 2, color: 'purple', info: 'Removes versions that are dead to every snapshot: deleted by a transaction that committed before the oldest running snapshot. One long transaction anywhere in the database holds this horizon back.' },
    { id: 'v1', label: 'v1 at (0,1)', sub: 'xmin 100, xmax 200', x: 2, y: 0, w: 1.5, color: 'teal', info: 'Created by transaction 100, superseded by transaction 200. Its t_ctid field points at v2, forming the update chain.' },
    { id: 'v2', label: 'v2 at (0,2)', sub: 'xmin 200, xmax 300', x: 2, y: 2, w: 1.5, color: 'teal', info: 'Created by 200, superseded by 300. Visible only to snapshots taken after 200 committed and before 300 committed.' },
    { id: 'v3', label: 'v3 at (0,3)', sub: 'xmin 300, xmax none', x: 2, y: 4, w: 1.5, color: 'green', info: 'The live version. xmax is empty, so it remains visible to every snapshot taken after 300 committed.' },
    { id: 's0', label: 'Report', sub: 'snapshot at XID 150', icon: '📊', x: 5, y: 0, w: 1.5, color: 'orange', info: 'A long Repeatable Read report started when only 100 had committed. Its snapshot never changes, so it keeps seeing v1 for hours, and keeps VACUUM from removing anything newer than XID 150.' },
    { id: 's1', label: 'Txn B', sub: 'snapshot at XID 250', x: 5, y: 2, w: 1.5, color: 'gray', info: 'Started after 200 committed and before 300 began: v1 is deleted for it, v3 does not exist yet, so it sees v2.' },
    { id: 's2', label: 'Txn C', sub: 'snapshot at XID 320', x: 5, y: 4, w: 1.5, color: 'gray', info: 'Started after 300 committed: sees only v3, the current version.' },
  ],
  edges: [
    { from: 'idx', to: 'v1', label: 'ctid' },
    { from: 'v1', to: 'v2', label: 't_ctid chain' },
    { from: 'v2', to: 'v3', label: 't_ctid chain' },
    { from: 's0', to: 'v1', label: 'visible', dashed: true },
    { from: 's1', to: 'v2', label: 'visible', dashed: true },
    { from: 's2', to: 'v3', label: 'visible', dashed: true },
    { from: 'vac', to: 'v1' },
    { from: 'vac', to: 'v2', label: 'prune' },
  ],
  steps: [
    { caption: 'Transaction 100 inserts row 42 as tuple v1 with xmin = 100 and no xmax. The index entry points at its ctid (0,1).', flows: [{ from: 'idx', to: 'v1', label: 'ctid (0,1)' }] },
    { caption: 'A long report starts at XID 150 and takes its snapshot: 100 is committed, nothing newer exists. At Repeatable Read this snapshot is used for the whole transaction.', flows: [{ from: 's0', to: 'v1', label: 'sees v1' }] },
    { caption: 'Transaction 200 updates the row. PostgreSQL never overwrites: it sets xmax = 200 on v1 and writes v2 with xmin = 200. Same page and no indexed column changed, so it is a HOT update and the index stays untouched.', flows: [{ from: 'v1', to: 'v2', label: 'UPDATE (HOT)' }] },
    { caption: 'Txn B snapshots at XID 250. Rule: visible if xmin committed before my snapshot and xmax did not. v1 fails (200 committed), v2 passes. The report still sees v1, because 200 lies in its future.', flows: [{ from: 's1', to: 'v2', label: 'sees v2' }, { from: 's0', to: 'v1', label: 'still v1' }] },
    { caption: 'Transaction 300 updates again: xmax = 300 on v2, new tuple v3. Three versions of one logical row now share the page, and no reader ever blocked a writer.', flows: [{ from: 'v2', to: 'v3', label: 'UPDATE (HOT)' }] },
    { caption: 'Txn C snapshots at XID 320 and sees only v3. Every reader followed the same chain and stopped at the version its snapshot allows, checking commit status in pg_xact.', flows: [{ from: 's2', to: 'v3', label: 'sees v3' }] },
    { caption: 'VACUUM runs, but the report (snapshot at 150) could still need v1, so the horizon is 150 and nothing is removed. This is how one forgotten transaction bloats every busy table in the database.', flows: [{ from: 'vac', to: 'v1', label: 'blocked' }], active: ['s0'] },
    { caption: 'The report commits and the horizon moves to 320. VACUUM prunes v1 and v2, redirects the line pointer to v3 and records free space. InnoDB gets the same effect differently: update in place, old versions in undo, purge trims undo.', flows: [{ from: 'vac', to: 'v2', label: 'prune v1, v2' }], active: ['v1', 'v3'] },
  ],
});

registerDiagram({
  id: 'stor-write-skew',
  roadmap: 'storage', module: 5, topic: 'Isolation Levels, Snapshot Isolation and MVCC Anomalies',
  kind: 'sequence',
  title: 'Write skew: snapshot isolation commits both, SERIALIZABLE aborts one',
  desc: 'Two on-call doctors both ask to leave. Each transaction checks the invariant on its own snapshot and updates a different row, so snapshot isolation sees no conflict. PostgreSQL SSI tracks what was read and aborts one of them.',
  actors: [
    { id: 'a', label: 'Txn A: Alice', sub: 'wants to go home', icon: '👩‍⚕️', color: 'blue', info: 'Runs: count doctors on call; if at least 2, set my on_call = false.' },
    { id: 'db', label: 'PostgreSQL', sub: 'doctors table', color: 'green', info: 'Invariant the business needs: at least one doctor on call. It is not expressed as a constraint, only checked by application code.' },
    { id: 'b', label: 'Txn B: Bob', sub: 'wants to go home', icon: '👨‍⚕️', color: 'orange', info: 'Runs exactly the same logic at the same moment for his own row.' },
  ],
  steps: [
    { section: 'REPEATABLE READ (snapshot isolation)' },
    { from: 'a', to: 'db', label: 'count on_call', caption: 'Alice\'s transaction takes its snapshot and counts doctors on call.' },
    { from: 'db', to: 'a', label: '2 on call', reply: true, caption: 'Two doctors are on call, so by the rule Alice may leave.' },
    { from: 'b', to: 'db', label: 'count on_call', caption: 'Bob\'s transaction starts before Alice commits. Its snapshot shows the same state.' },
    { from: 'db', to: 'b', label: '2 on call', reply: true, caption: 'Bob also sees two doctors on call: the check passes for him too.' },
    { from: 'a', to: 'db', label: 'UPDATE alice: off', caption: 'Alice updates her own row. A write lock on the alice row only.' },
    { from: 'b', to: 'db', label: 'UPDATE bob: off', caption: 'Bob updates a different row, so there is no write-write conflict and nothing blocks.' },
    { from: 'a', to: 'db', label: 'COMMIT', caption: 'Alice commits successfully.' },
    { from: 'b', to: 'db', label: 'COMMIT', caption: 'Bob commits as well. There is no row both transactions wrote, so first-committer-wins has nothing to check.' },
    { from: 'db', to: 'b', label: 'OK: 0 on call', reply: true, caption: 'Both commits succeed. Each transaction was correct on its own snapshot, yet together they broke the invariant. Snapshot isolation only checks writes against writes, never what was read.' },
    { section: 'SERIALIZABLE (SSI)' },
    { from: 'a', to: 'db', label: 'read, UPDATE, COMMIT', caption: 'Same steps at SERIALIZABLE. Reads now leave SIREAD locks recording which rows and ranges each transaction read; they block nothing.' },
    { from: 'b', to: 'db', label: 'read, UPDATE, COMMIT', caption: 'Bob\'s update writes a row Alice read, and Alice\'s writes a row Bob read: two read-write dependencies forming a dangerous cycle.' },
    { from: 'db', to: 'a', label: 'COMMIT OK', reply: true, caption: 'The first committer wins. Alice goes home.' },
    { from: 'db', to: 'b', label: 'ERROR 40001', reply: true, caption: 'Bob gets "could not serialize access due to read/write dependencies". No damage was done, but the application must be ready for this error.' },
    { from: 'b', to: 'db', label: 'retry: count on_call', caption: 'A generic retry wrapper reruns the whole transaction with a fresh snapshot.' },
    { from: 'db', to: 'b', label: '1 on call', reply: true, caption: 'Only one doctor is on call now.' },
    { from: 'b', to: 'b', label: 'refuse, stay on', caption: 'Bob\'s logic refuses and the invariant holds. Alternatives: SELECT ... FOR UPDATE on the rows the decision depends on, or one shift row that both must decrement atomically.' },
  ],
});

registerDiagram({
  id: 'stor-iceberg-commit',
  roadmap: 'storage', module: 5, topic: 'Lakehouse Table Formats and Object-Storage-Native Databases',
  kind: 'graph',
  title: 'Apache Iceberg: metadata tree and an atomic commit on object storage',
  desc: 'Every file in an Iceberg table is immutable; the only mutable thing is the catalog pointer to the current metadata file. Follow a read through the metadata tree, then two writers racing to commit with compare-and-swap.',
  groups: [
    { id: 'meta', label: 'Metadata (object storage)', x: 0.5, y: 2, w: 4, h: 5, color: 'blue' },
    { id: 'data', label: 'Data files (Parquet)', x: 0, y: 7.65, w: 5, h: 1.35, color: 'green' },
  ],
  nodes: [
    { id: 'reader', label: 'Query engine', sub: 'Trino, Spark, DuckDB', icon: '🔎', x: 0, y: 0, color: 'gray', info: 'Any engine that speaks Iceberg. It needs only the catalog and object storage: planning works from metadata, so it never LISTs the data prefix.' },
    { id: 'catalog', label: 'Catalog', sub: 'orders → v42', x: 2, y: 0, w: 1.5, color: 'purple', info: 'REST catalog (Polaris, Unity, S3 Tables), Glue or Hive Metastore. It stores one pointer per table and offers an atomic compare-and-swap on it. That single primitive is what makes multi-file commits atomic.' },
    { id: 'mjson', label: 'v42.metadata.json', sub: 'schema, snapshots', x: 2, y: 2, w: 1.5, color: 'blue', info: 'Table schema, partition spec, sort order, properties and the list of snapshots with the id of the current one. Every commit writes a new metadata file; old ones remain until cleaned up.' },
    { id: 'mlist', label: 'Manifest list', sub: 'one per snapshot', x: 2, y: 4, w: 1.5, color: 'blue', info: 'Lists the manifests that make up this snapshot, with partition value ranges per manifest, so whole manifests can be skipped during planning.' },
    { id: 'man1', label: 'Manifest A', sub: 'files + col stats', x: 1, y: 6, color: 'blue', info: 'Each entry is a data or delete file with its partition, record count and per-column min, max and null counts used for pruning.' },
    { id: 'man2', label: 'Manifest B', sub: 'files + col stats', x: 3, y: 6, color: 'blue', info: 'Manifests are reused across snapshots: a commit that appends rows writes one new manifest and references the old ones unchanged.' },
    { id: 'd1', label: 'part-001', sub: 'day=2026-10-27', x: 0, y: 8, color: 'green', info: 'Immutable Parquet file, typically 256 MB to 1 GB. Never modified: deletes go to delete files (merge-on-read) or cause a rewrite (copy-on-write).' },
    { id: 'd2', label: 'part-002', sub: 'day=2026-10-28', x: 2, y: 8, color: 'green', info: 'Pruned by partition and column statistics when a query does not need it.' },
    { id: 'd3', label: 'new files', sub: 'written by A', x: 4, y: 8, color: 'teal', enter: 4, info: 'Writer A\'s new Parquet files. They are invisible until a committed snapshot references them; if A crashes they become orphan files for cleanup.' },
    { id: 'wA', label: 'Writer A', sub: 'streaming append', x: 6, y: 4, color: 'orange', info: 'Commits a micro-batch every minute or so. Appends rarely conflict with anything.' },
    { id: 'wB', label: 'Writer B', sub: 'compaction job', x: 6, y: 1.5, color: 'red', info: 'Rewrites small files into big ones. Conflicts only if someone else deleted or rewrote the same files in the meantime.' },
  ],
  edges: [
    { from: 'reader', to: 'catalog', label: 'load table' },
    { from: 'catalog', to: 'mjson' },
    { from: 'mjson', to: 'mlist' },
    { from: 'mlist', to: 'man1' },
    { from: 'mlist', to: 'man2' },
    { from: 'man1', to: 'd1' },
    { from: 'man1', to: 'd2' },
    { from: 'man2', to: 'd3' },
    { from: 'wA', to: 'd3', label: 'write files' },
    { from: 'wA', to: 'catalog', label: 'CAS v42 → v43' },
    { from: 'wB', to: 'catalog', label: 'CAS v42 → v43' },
  ],
  steps: [
    { caption: 'An engine loads table orders. The catalog holds one mutable thing: a pointer to the current metadata file, v42.metadata.json.', flows: [{ from: 'reader', to: 'catalog', label: 'current?' }] },
    { caption: 'The metadata file gives schema, partition spec and the current snapshot, which points to a manifest list. The manifest list carries partition ranges per manifest, so planning skips whole manifests.', flows: [{ from: 'catalog', to: 'mjson', label: 'v42' }, { from: 'mjson', to: 'mlist', label: 'snapshot 42' }] },
    { caption: 'Manifests list data files with per-column min/max. The planner prunes by partition and statistics without a single LIST call on the bucket, then reads only the surviving Parquet files.', flows: [{ from: 'mlist', to: 'man1', label: 'prune' }, { from: 'man1', to: 'd2', label: 'read part-002' }] },
    { caption: 'Writer A appends: it writes new Parquet files, a new manifest, a manifest list and v43.metadata.json, all under unique names. Nothing points at them yet, so no reader can see half a commit.', flows: [{ from: 'wA', to: 'd3', label: 'new Parquet' }] },
    { caption: 'Commit is a compare-and-swap on the catalog pointer: set v43 only if the table is still at v42. It succeeds atomically; this single conditional update is the linearization point.', flows: [{ from: 'wA', to: 'catalog', label: 'CAS 42 → 43 ✓' }], active: ['man2', 'd3'] },
    { caption: 'Writer B (compaction) also planned against v42, so its CAS fails. It re-reads v43, checks whether A touched the files it rewrote (an append does not), rebases as v44 and retries.', flows: [{ from: 'wB', to: 'catalog', label: 'CAS 42 → 43 ✗' }] },
    { caption: 'Readers that loaded v42 keep reading it: files are immutable, which gives snapshot isolation and time travel. Delta Lake gets the same with put-if-absent of _delta_log/...043.json, now native in S3 via If-None-Match.', active: ['reader', 'mjson', 'd1', 'd2'] },
    { caption: 'Housekeeping is mandatory: compaction merges small files, expire_snapshots drops old snapshots, remove_orphan_files deletes leftovers of failed commits. Skip it and planning slows and storage grows: the lakehouse VACUUM.', active: ['wB', 'man1', 'man2', 'd1', 'd2', 'd3'] },
  ],
});

// ===== Module 6: Distributed Storage Systems ==================================

registerDiagram({
  id: 'stor-replication-sync-async',
  roadmap: 'storage', module: 6, topic: 'Replication Strategies: Sync, Async, Consensus and Chain Replication',
  kind: 'sequence',
  title: 'Sync vs async followers: who still has the write after failover?',
  desc: 'The leader waits for the synchronous follower before acknowledging, but ships to the async follower in the background. When the leader dies, the choice of which follower to promote decides whether acknowledged writes survive.',
  actors: [
    { id: 'c', label: 'Client', icon: '💻', color: 'gray', info: 'Treats "COMMIT OK" as a promise that the order exists.' },
    { id: 'l', label: 'Leader', sub: 'primary', icon: '👑', color: 'blue', info: 'Orders all writes and streams its log (PostgreSQL WAL, MySQL binlog) to followers.' },
    { id: 'a', label: 'Follower A', sub: 'sync (other AZ)', color: 'green', info: 'Listed in synchronous_standby_names (PostgreSQL) or acting as a semi-sync replica (MySQL). The leader waits for its acknowledgement before confirming commits.' },
    { id: 'b', label: 'Follower B', sub: 'async (other region)', color: 'orange', info: 'Receives the log with a delay (replication lag of milliseconds to seconds, more under load). Useful for read scaling and DR, but may be missing recent commits.' },
  ],
  steps: [
    { section: 'Commit with one sync follower' },
    { from: 'c', to: 'l', label: 'INSERT order 42', caption: 'The client sends a write. Only the leader accepts writes, so it orders everything and there are no write conflicts.' },
    { from: 'l', to: 'l', label: 'write + flush WAL', caption: 'The leader makes the change durable on its own disk first.' },
    { from: 'l', to: 'a', label: 'ship WAL record', caption: 'The record is streamed to follower A. The leader waits: commit latency now includes one round trip to A (about 1 ms across AZs, 50 to 100 ms across regions).' },
    { from: 'a', to: 'l', label: 'ack (flushed)', reply: true, caption: 'A confirms the record is durable. PostgreSQL synchronous_commit levels choose what A must do first: remote_write, on (flushed) or remote_apply (visible to reads on A).' },
    { from: 'l', to: 'c', label: 'COMMIT OK', reply: true, caption: 'Only now is the client told the write succeeded. Two copies exist, so losing any single node loses nothing.' },
    { from: 'l', to: 'b', label: 'ship WAL (async)', caption: 'Follower B receives the record later. A read from B right now would not see order 42: a read-your-writes violation. Fix it by reading from the leader or waiting for B to reach your commit LSN.' },
    { section: 'Leader crashes before B catches up' },
    { from: 'l', to: 'l', label: 'crash', caption: 'The leader dies. Order 42 exists on A, but not yet on B.' },
    { from: 'b', to: 'b', label: 'promote? 42 lost', caption: 'Promoting the async follower loses order 42, a write the client was told succeeded. That is RPO > 0, the price of async replication.' },
    { from: 'a', to: 'a', label: 'promote: has 42', caption: 'Promoting the sync follower loses nothing. The old leader must be fenced (epoch or lease checks) so it cannot come back and accept writes: two leaders is split brain.' },
    { from: 'c', to: 'a', label: 'writes resume on A', caption: 'Trade-off: if A is down the leader cannot commit at all, so MySQL semi-sync falls back to async after a timeout, silently reopening the data-loss window. Consensus (Raft) avoids picking by waiting for any majority.' },
  ],
});

registerDiagram({
  id: 'stor-quorum-nwr',
  roadmap: 'storage', module: 6, topic: 'Quorum Reads and Writes',
  kind: 'graph',
  title: 'N=3, W=2, R=2: a write with a replica down, then a read that repairs it',
  desc: 'Because W + R > N, every read set overlaps every write set in at least one replica. Follow a write while r3 is unreachable, then a read that hits the stale r3 and still returns the newest value.',
  groups: [
    { id: 'ring', label: 'Replicas of key user:7', x: 4, y: 0, w: 3, h: 5, color: 'green' },
  ],
  nodes: [
    { id: 'client', label: 'Client', sub: 'CL = QUORUM', icon: '💻', x: 0, y: 2, color: 'gray', info: 'Chooses the consistency level per request: ONE, QUORUM, LOCAL_QUORUM, ALL.' },
    { id: 'coord', label: 'Coordinator', sub: 'any node', x: 2, y: 2, color: 'blue', info: 'Leaderless: whichever node receives the request forwards it to the N replicas that own the key (by consistent hashing) and counts responses.' },
    { id: 'hint', label: 'Hinted handoff', sub: 'hint for r3', x: 2, y: 4, color: 'purple', ghost: true, enter: 4, info: 'The coordinator keeps the missed write and replays it when r3 returns (Cassandra keeps hints for up to 3 hours by default). Hints do not count towards W in Cassandra. Dynamo-style sloppy quorums do count substitutes, which breaks the overlap guarantee.' },
    { id: 'r1', label: 'Replica r1', sub: 'v2 @ t2', x: 4, y: 0, shape: 'db', color: 'green' },
    { id: 'r2', label: 'Replica r2', sub: 'v2 @ t2', x: 4, y: 2, shape: 'db', color: 'green', info: 'The replica that is in both the write set {r1, r2} and the read set {r2, r3}. W + R > N guarantees at least one such replica exists.' },
    { id: 'r3', label: 'Replica r3', sub: 'stale: v1 @ t1', x: 4, y: 4, shape: 'db', color: 'orange', info: 'Missed the write while unreachable, so it still holds v1 until read repair, hint replay or anti-entropy repair (Merkle-tree comparison, nodetool repair) fixes it.' },
    { id: 'down', label: 'r3 unreachable', sub: 'GC pause / partition', x: 6, y: 4, color: 'red', enter: 2, exit: 5, info: 'From the coordinator\'s side a slow node and a dead node look the same: the request simply times out.' },
  ],
  edges: [
    { from: 'client', to: 'coord', label: 'write / read' },
    { from: 'coord', to: 'r1' },
    { from: 'coord', to: 'r2' },
    { from: 'coord', to: 'r3' },
    { from: 'coord', to: 'hint' },
    { from: 'hint', to: 'r3', label: 'replay later' },
  ],
  steps: [
    { caption: 'The client writes v2 of user:7 with timestamp t2. Any node can coordinate; there is no leader to fail over.', flows: [{ from: 'client', to: 'coord', label: 'write v2' }] },
    { caption: 'The coordinator sends the write to all N=3 replicas in parallel, not just W of them. r3 is unreachable, so its request times out.', flows: [{ from: 'coord', to: 'r1', label: 'v2' }, { from: 'coord', to: 'r2', label: 'v2' }, { from: 'coord', to: 'r3', label: 'times out' }] },
    { caption: 'r1 and r2 acknowledge. W=2 is met, so the client gets success while one replica is down: quorums tolerate N - W = 1 failure for writes.', flows: [{ from: 'r1', to: 'coord', label: 'ack' }, { from: 'r2', to: 'coord', label: 'ack' }, { from: 'coord', to: 'client', label: 'OK (2 of 3)' }] },
    { caption: 'The coordinator stores a hint for r3 so the missed write can be delivered when r3 comes back.', flows: [{ from: 'coord', to: 'hint', label: 'store hint' }] },
    { caption: 'r3 is back, but the hint has not been replayed yet. A read at R=2 asks two replicas, here r2 and r3, which return v2 @ t2 and v1 @ t1.', flows: [{ from: 'client', to: 'coord', label: 'read' }, { from: 'coord', to: 'r2', label: 'read' }, { from: 'coord', to: 'r3', label: 'read' }] },
    { caption: 'W + R = 4 > N = 3, so the read set must include a replica that took the write (r2). The coordinator returns the value with the newest timestamp: v2.', flows: [{ from: 'r2', to: 'coord', label: 'v2 @ t2' }, { from: 'r3', to: 'coord', label: 'v1 @ t1' }, { from: 'coord', to: 'client', label: 'v2' }] },
    { caption: 'Read repair: having seen r3 is stale, the coordinator writes v2 back to it. Hint replay and periodic anti-entropy repair catch the keys nobody reads.', flows: [{ from: 'coord', to: 'r3', label: 'repair v2' }, { from: 'hint', to: 'r3', label: 'replay' }] },
    { caption: 'Quorums are still not linearizable: a write that reached only 1 replica "fails" but is not rolled back and may be read later, and last-write-wins with clock skew silently drops concurrent writes. Use LWT, Paxos or CRDTs when it matters.', active: ['r1', 'r2', 'r3', 'coord'] },
  ],
});

registerDiagram({
  id: 'stor-hdfs-write-pipeline',
  roadmap: 'storage', module: 6, topic: 'Metadata Services and the GFS / HDFS Architecture',
  kind: 'graph',
  title: 'HDFS write: NameNode picks DataNodes, bytes flow through a pipeline',
  desc: 'The NameNode owns metadata only; file bytes never pass through it. The client streams packets to the first DataNode, which forwards them down a replication pipeline placed across racks. Includes a DataNode failure mid-block.',
  groups: [
    { id: 'meta', label: 'Metadata (control plane)', x: 2, y: 0, w: 3, h: 1, color: 'blue' },
    { id: 'rackA', label: 'Rack A', x: 2, y: 2, w: 1, h: 2, color: 'green' },
    { id: 'rackB', label: 'Rack B', x: 4, y: 2, w: 3, h: 4, color: 'green' },
  ],
  nodes: [
    { id: 'client', label: 'HDFS client', sub: 'on DataNode dn1', icon: '💻', x: 0, y: 3, color: 'gray', info: 'Writes are append-only: no random overwrites, which is what lets HDFS keep the design simple. Typical blocks are 128 MB.' },
    { id: 'nn', label: 'NameNode', sub: 'namespace + blocks', x: 2, y: 0, color: 'blue', info: 'Holds the whole namespace and the block → DataNode map in RAM (about 150 bytes per file, directory or block, hence the small-files problem). Persists changes as an edit log plus periodic fsimage checkpoints.' },
    { id: 'jn', label: 'JournalNodes', sub: 'edit log quorum', x: 4, y: 0, color: 'blue', info: 'In HA mode the active NameNode writes every edit to a majority of (usually 3) JournalNodes; the standby tails them and stays hot. ZooKeeper failover controllers plus fencing prevent two active NameNodes.' },
    { id: 'dn1', label: 'DataNode dn1', sub: 'replica 1 (local)', x: 2, y: 3, shape: 'db', color: 'green', info: 'First replica goes on the writer\'s own node when the client runs inside the cluster, which saves one network hop.' },
    { id: 'dn2', label: 'DataNode dn2', sub: 'replica 2', x: 4, y: 3, shape: 'db', color: 'green', exit: 6 },
    { id: 'dn3', label: 'DataNode dn3', sub: 'replica 3', x: 6, y: 3, shape: 'db', color: 'green', info: 'Replicas 2 and 3 share a rack different from replica 1: the block survives losing a whole rack, while only one copy crosses the inter-rack link.' },
    { id: 'dn4', label: 'DataNode dn4', sub: 'new replica', x: 5, y: 5, shape: 'db', color: 'teal', enter: 7, info: 'Chosen by the NameNode to restore the replication factor to 3 after dn2 failed.' },
  ],
  edges: [
    { from: 'client', to: 'nn', label: 'create / addBlock' },
    { from: 'nn', to: 'jn', label: 'edits' },
    { from: 'client', to: 'dn1', label: 'packets' },
    { from: 'dn1', to: 'dn2', label: 'pipeline' },
    { from: 'dn2', to: 'dn3', label: 'pipeline' },
    { from: 'dn1', to: 'nn', label: 'block reports' },
    { from: 'dn3', to: 'dn4' },
  ],
  steps: [
    { caption: 'The client asks the NameNode to create /logs/day.log. The NameNode checks permissions and that the file does not exist, then makes the edit durable on a quorum of JournalNodes.', flows: [{ from: 'client', to: 'nn', label: 'create' }, { from: 'nn', to: 'jn', label: 'OP_ADD' }] },
    { caption: 'For each 128 MB block the client calls addBlock. The NameNode replies with a block ID and three DataNodes chosen with rack awareness: dn1 local, then dn2 and dn3 on another rack.', flows: [{ from: 'nn', to: 'client', label: 'dn1, dn2, dn3' }] },
    { caption: 'The client streams 64 KiB packets straight to dn1. The NameNode stays off the data path, which is why one NameNode can serve thousands of DataNodes.', flows: [{ from: 'client', to: 'dn1', label: 'packet' }] },
    { caption: 'Each DataNode writes the packet locally and forwards it to the next in parallel. A pipeline (chain) uses every network link once, instead of the client sending three copies.', flows: [{ from: 'dn1', to: 'dn2', label: 'packet' }, { from: 'dn2', to: 'dn3', label: 'packet' }] },
    { caption: 'Acks flow back up the chain. A packet stays in the client\'s ack queue until all three replicas confirm it.', flows: [{ from: 'dn3', to: 'dn2', label: 'ack' }, { from: 'dn2', to: 'dn1', label: 'ack' }, { from: 'dn1', to: 'client', label: 'ack' }] },
    { caption: 'dn2 dies mid-block. The client closes the pipeline, moves unacked packets back to the send queue and rebuilds the pipeline from the healthy nodes (dn1 → dn3) under a new generation stamp so stale replicas are rejected.', flows: [{ from: 'dn1', to: 'dn3', label: 'resume' }], active: ['rackB'] },
    { caption: 'The block finishes with 2 replicas. DataNodes report it via heartbeats and block reports; the NameNode sees it is under-replicated and tells dn3 to copy it to dn4.', flows: [{ from: 'dn1', to: 'nn', label: 'block report' }, { from: 'dn3', to: 'dn4', label: 're-replicate' }] },
    { caption: 'Metadata is the bottleneck and the risk: every file costs NameNode heap, so 100 million small files exhaust it. HA needs JournalNodes plus fencing; Colossus and object stores shard metadata instead.', active: ['nn', 'jn', 'meta'] },
  ],
});

registerDiagram({
  id: 'stor-ceph-crush',
  roadmap: 'storage', module: 6, topic: 'Ceph: RADOS, CRUSH and Placement Groups',
  kind: 'graph',
  title: 'Ceph placement: object → PG → CRUSH → OSDs across racks',
  desc: 'Ceph has no lookup table of object locations. Clients hash the name to a placement group and run CRUSH on the cluster map to compute which OSDs hold it, honouring failure domains. Follow a write, then an OSD failure and the resulting backfill.',
  groups: [
    { id: 'rackA', label: 'Rack A', x: 4, y: 0, w: 3, h: 1, color: 'green' },
    { id: 'rackB', label: 'Rack B', x: 4, y: 2, w: 3, h: 1, color: 'green' },
    { id: 'rackC', label: 'Rack C', x: 4, y: 4, w: 3, h: 1, color: 'green' },
  ],
  nodes: [
    { id: 'mon', label: 'MON quorum', sub: 'OSD + CRUSH maps', x: 0, y: 0, color: 'blue', info: 'A small Paxos cluster (3 or 5 MONs) holding the authoritative cluster maps. Every change, such as an OSD going down, produces a new map epoch that clients and OSDs pick up incrementally.' },
    { id: 'crush', label: 'CRUSH rule', sub: 'one replica per rack', x: 2, y: 0, color: 'purple', info: 'The CRUSH map describes the hierarchy (root, rack, host, OSD) and weights by capacity. A rule such as "choose 3 racks, then 1 OSD in each" turns a PG id into an ordered list of OSDs, pseudo-randomly but deterministically.' },
    { id: 'cli', label: 'Client', sub: 'RBD / RGW / CephFS', icon: '💻', x: 0, y: 2, color: 'gray', info: 'Clients cache the cluster map and compute placement themselves, then talk to OSDs directly. The MONs are never on the data path.' },
    { id: 'pg', label: 'PG 2.6', sub: 'hash(name) % pg_num', x: 2, y: 2, color: 'yellow', info: 'Placement groups bucket objects (pool 2, PG 6). Placement, peering, recovery and scrubbing all work per PG, which keeps metadata small and recovery parallel. Aim for about 100 PGs per OSD; the autoscaler manages pg_num.' },
    { id: 'osd1', label: 'osd.1', sub: 'replica', x: 4, y: 0, shape: 'db', color: 'teal', info: 'Holds a replica of PG 2.6 in rack A. When it fails, only the PGs that mapped to it need to move.' },
    { id: 'osd7', label: 'osd.7', sub: 'rack A, spare room', x: 6, y: 0, shape: 'db', color: 'teal', info: 'Another OSD in rack A. After osd.1 is marked out, CRUSH picks it for PG 2.6, so the rule "one replica per rack" still holds.' },
    { id: 'osd3', label: 'osd.3', sub: 'primary', x: 4, y: 2, shape: 'db', color: 'blue', info: 'First OSD in the acting set: it orders writes for the PG, replicates to the others and serves reads by default.' },
    { id: 'osd4', label: 'osd.4', sub: 'other PGs', x: 6, y: 2, shape: 'db', color: 'gray', info: 'Holds replicas of other placement groups. Every OSD is primary for some PGs and replica for others, so load and recovery spread across the cluster.' },
    { id: 'osd5', label: 'osd.5', sub: 'replica', x: 4, y: 4, shape: 'db', color: 'teal', info: 'Third replica of PG 2.6, in rack C.' },
    { id: 'osd8', label: 'osd.8', sub: 'other PGs', x: 6, y: 4, shape: 'db', color: 'gray', info: 'Another OSD in rack C serving other placement groups.' },
  ],
  edges: [
    { from: 'mon', to: 'cli', label: 'cluster map' },
    { from: 'mon', to: 'crush', label: 'stores' },
    { from: 'cli', to: 'pg', label: 'hash' },
    { from: 'crush', to: 'pg', label: 'rule' },
    { from: 'pg', to: 'osd3', label: 'acting [3, 1, 5]' },
    { from: 'osd3', to: 'osd1', label: 'replicate' },
    { from: 'osd3', to: 'osd5', label: 'replicate' },
    { from: 'osd3', to: 'osd7', label: 'backfill' },
  ],
  steps: [
    { caption: 'The client fetches the cluster map from the MON quorum: the OSD map (which OSDs exist and are up), the CRUSH map (hierarchy and weights) and pool rules, versioned by epoch.', flows: [{ from: 'mon', to: 'cli', label: 'map epoch 812' }] },
    { caption: 'To write object img-123 in pool 2, the client hashes the name: hash("img-123") mod pg_num = 6, so PG 2.6. No lookup service is involved, just arithmetic on the name.', flows: [{ from: 'cli', to: 'pg', label: 'img-123 → 2.6' }] },
    { caption: 'CRUSH(PG 2.6, map, rule "one replica per rack") descends root → rack → host → OSD, weighted by capacity, and returns the acting set [3, 1, 5]. Every client and OSD computes the same answer.', flows: [{ from: 'crush', to: 'pg', label: 'rule' }, { from: 'pg', to: 'osd3', label: '[3, 1, 5]' }] },
    { caption: 'The client sends the write straight to the primary, osd.3, in rack B. The data path never touches the MONs, which is why Ceph scales to thousands of OSDs.', flows: [{ from: 'pg', to: 'osd3', label: 'write img-123' }] },
    { caption: 'The primary forwards the write to osd.1 and osd.5 in parallel and acknowledges only after all OSDs in the acting set have persisted it. Three racks, so losing any rack loses one copy.', flows: [{ from: 'osd3', to: 'osd1', label: 'replica' }, { from: 'osd3', to: 'osd5', label: 'replica' }] },
    { caption: 'osd.1 dies. Peers report it down; after mon_osd_down_out_interval (10 minutes) it is marked out and the map epoch increments. Rerunning CRUSH for PG 2.6 now yields [3, 7, 5]. Only PGs that used osd.1 move.', flows: [{ from: 'mon', to: 'cli', label: 'epoch 813' }], active: ['osd1', 'osd7'] },
    { caption: 'The PG peers and osd.3 backfills it to osd.7, throttled (osd_max_backfills, mClock) so clients keep their latency. Thousands of PGs recover in parallel across many OSDs, which keeps MTTR short.', flows: [{ from: 'osd3', to: 'osd7', label: 'backfill PG 2.6' }] },
    { caption: 'Compare: HDFS stores every block location in the NameNode; a hash ring is flat and unaware of racks. CRUSH is a weighted, hierarchy-aware placement function. Too few PGs per OSD makes data uneven; the autoscaler targets about 100.', active: ['crush', 'pg', 'osd4', 'osd8'] },
  ],
});

